&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;💡运行后效果（部分输出示例）：&#34;&gt;&lt;a href=&#34;#💡运行后效果（部分输出示例）：&#34; class=&#34;headerlink&#34; title=&#34;💡运行后效果（部分输出示例）：&#34;&gt;&lt;/a&gt;💡运行后效果（部分输出示例）：&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;️⃣  获取当前时间、日期、时间戳
当前时间： &lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;11&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;42&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10.232432&lt;/span&gt;
当前日期： &lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;
当前时间部分： &lt;span class=&#34;token number&#34;&gt;11&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;42&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10.232432&lt;/span&gt;
当前时间戳（秒）： &lt;span class=&#34;token number&#34;&gt;1760643730.232432&lt;/span&gt;

&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;️⃣  创建自定义日期与时间对象
日期对象： &lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;
时间对象： &lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;45&lt;/span&gt;
完整日期时间对象： &lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;45&lt;/span&gt;

&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;
当前时段： 早上 🌅
&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;
✅ 结束：datetime 模块演示完毕&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

 &lt;h2 id=&#34;psycopg2-详细使用教程：从入门到精通&#34;&gt;&lt;a href=&#34;#psycopg2-详细使用教程：从入门到精通&#34; class=&#34;headerlink&#34; title=&#34;psycopg2 详细使用教程：从入门到精通&#34;&gt;&lt;/a&gt;psycopg2 详细使用教程：从入门到精通&lt;/h2&gt;&lt;h3 id=&#34;1-什么是-psycopg2？&#34;&gt;&lt;a href=&#34;#1-什么是-psycopg2？&#34; class=&#34;headerlink&#34; title=&#34;1. 什么是 psycopg2？&#34;&gt;&lt;/a&gt;1. 什么是 psycopg2？&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PostgreSQL:&lt;/strong&gt; 一款功能极其强大的开源对象-关系型数据库系统。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;psycopg2:&lt;/strong&gt; 一个 Python 库，充当 Python 应用程序和 PostgreSQL 数据库之间的“驱动”或“适配器”。它实现了 Python DB-API 2.0 规范，允许你使用标准的 Python 代码来执行 SQL 命令。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;2-安装&#34;&gt;&lt;a href=&#34;#2-安装&#34; class=&#34;headerlink&#34; title=&#34;2. 安装&#34;&gt;&lt;/a&gt;2. 安装&lt;/h3&gt;&lt;p&gt;安装 &lt;code&gt;psycopg2&lt;/code&gt; 有两种常见方式：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;推荐 (用于开发和学习):&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;pip install psycopg2-binary&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;这个包预编译了所有必需的库，安装最简单，开箱即用。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;用于生产环境 (需要编译):&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;pip install psycopg2&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;这需要你在系统上安装了 &lt;code&gt;libpq&lt;/code&gt;（PostgreSQL 的 C 库）和相关的开发工具。它性能更好，但安装更复杂。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;对于本教程，我们假设你已使用 &lt;code&gt;psycopg2-binary&lt;/code&gt;。&lt;/strong&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;3-核心工作流：连接与游标-Cursor&#34;&gt;&lt;a href=&#34;#3-核心工作流：连接与游标-Cursor&#34; class=&#34;headerlink&#34; title=&#34;3. 核心工作流：连接与游标 (Cursor)&#34;&gt;&lt;/a&gt;3. 核心工作流：连接与游标 (Cursor)&lt;/h3&gt;&lt;p&gt;与数据库的所有交互都遵循以下模式：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;连接 (Connect):&lt;/strong&gt; 建立到 PostgreSQL 服务器的连接。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;游标 (Cursor):&lt;/strong&gt; 创建一个游标对象。游标是执行 SQL 命令的“手柄”。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;执行 (Execute):&lt;/strong&gt; 使用游标执行 SQL 语句。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;获取 (Fetch):&lt;/strong&gt; (如果是 &lt;code&gt;SELECT&lt;/code&gt; 语句) 从游标中取出结果。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;提交 (Commit):&lt;/strong&gt; (如果是 &lt;code&gt;INSERT&lt;/code&gt;, &lt;code&gt;UPDATE&lt;/code&gt;, &lt;code&gt;DELETE&lt;/code&gt;) 提交事务，使更改永久生效。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;关闭 (Close):&lt;/strong&gt; 关闭游标和连接，释放资源。&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;4-【重要】最佳实践：使用-with-语句&#34;&gt;&lt;a href=&#34;#4-【重要】最佳实践：使用-with-语句&#34; class=&#34;headerlink&#34; title=&#34;4. 【重要】最佳实践：使用 with 语句&#34;&gt;&lt;/a&gt;4. 【重要】最佳实践：使用 &lt;code&gt;with&lt;/code&gt; 语句&lt;/h3&gt;&lt;p&gt;手动管理 &lt;code&gt;connect()&lt;/code&gt; 和 &lt;code&gt;close()&lt;/code&gt; 非常容易出错（比如程序崩溃时连接未关闭）。&lt;code&gt;psycopg2&lt;/code&gt; 的连接和游标对象都是&lt;strong&gt;上下文管理器&lt;/strong&gt;，必须使用 &lt;code&gt;with&lt;/code&gt; 语句来自动管理资源。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;这是本教程推荐的标准模式：&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;import psycopg2
import sys

# 数据库连接参数
# 强烈建议使用环境变量或配置文件，不要硬编码
DB_PARAMS = {
    &#39;host&#39;: &#39;localhost&#39;,      # 数据库主机
    &#39;port&#39;: 5432,             # 端口 (默认 5432)
    &#39;user&#39;: &#39;postgres&#39;,       # 你的用户名
    &#39;password&#39;: &#39;your_password&#39;, # 你的密码
    &#39;dbname&#39;: &#39;test_db&#39;       # 你要连接的数据库
}

try:
    # 1. 建立连接
    # with 语句确保连接在使用后自动关闭
    with psycopg2.connect(**DB_PARAMS) as conn:

        # 2. 创建游标
        # with 语句确保游标在使用后自动关闭
        with conn.cursor() as cur:

            # 3. 执行 SQL
            cur.execute(&#34;SELECT version();&#34;)

            # 4. 获取结果
            db_version = cur.fetchone() # fetchone() 获取一条结果
            print(f&#34;数据库版本: {db_version[0]}&#34;)

            # 5. 提交 (对于 SELECT 不是必需的, 但对于 DML 是必需的)
            # conn.commit() # 在这里，with conn 会自动处理

except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;连接数据库时出错: {error}&#34;)
    sys.exit(1)

# 6. 关闭
# 在 &#39;with&#39; 块结束时，cur.close() 和 conn.close() 已自动调用
print(&#34;连接已自动关闭。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;5-【极其重要】防止-SQL-注入：参数化查询&#34;&gt;&lt;a href=&#34;#5-【极其重要】防止-SQL-注入：参数化查询&#34; class=&#34;headerlink&#34; title=&#34;5. 【极其重要】防止 SQL 注入：参数化查询&#34;&gt;&lt;/a&gt;5. 【极其重要】防止 SQL 注入：参数化查询&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;永远不要&lt;/strong&gt;使用 Python 的字符串格式化（如 &lt;code&gt;f-string&lt;/code&gt; 或 &lt;code&gt;%&lt;/code&gt;）来构建 SQL 查询。这会导致严重的安全漏洞（SQL 注入）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;错误的方式 (危险!)：&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# 千万不要这样做！
user_id = &#34;105 OR 1=1&#34;
cur.execute(f&#34;SELECT * FROM users WHERE id = {user_id}&#34;) &lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;正确的方式 (安全)：&lt;/strong&gt; &lt;code&gt;psycopg2&lt;/code&gt; 会自动为你处理所有特殊字符的转义。你需要在 SQL 语句中使用 &lt;code&gt;%s&lt;/code&gt; 作为占位符，然后将一个&lt;strong&gt;元组 (tuple)&lt;/strong&gt; 作为第二个参数传递给 &lt;code&gt;execute()&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# 正确的方式：使用占位符
user_id = &#34;105&#34;
query = &#34;SELECT * FROM users WHERE id = %s&#34;

# 注意：即使只有一个参数，也必须将其放在元组中 (user_id,)
cur.execute(query, (user_id,))&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;注意&lt;/strong&gt;：&lt;code&gt;psycopg2&lt;/code&gt; 统一使用 &lt;code&gt;%s&lt;/code&gt; 作为占位符，&lt;strong&gt;无论数据类型是字符串、数字还是日期&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h3 id=&#34;6-CRUD-操作详解&#34;&gt;&lt;a href=&#34;#6-CRUD-操作详解&#34; class=&#34;headerlink&#34; title=&#34;6. CRUD 操作详解&#34;&gt;&lt;/a&gt;6. CRUD 操作详解&lt;/h3&gt;&lt;p&gt;让我们创建一个 &lt;code&gt;employees&lt;/code&gt; 表并对其进行操作。&lt;/p&gt;
&lt;h4 id=&#34;A-创建表-CREATE&#34;&gt;&lt;a href=&#34;#A-创建表-CREATE&#34; class=&#34;headerlink&#34; title=&#34;A. 创建表 (CREATE)&#34;&gt;&lt;/a&gt;A. 创建表 (CREATE)&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;create_table_query = &#34;&#34;&#34;
CREATE TABLE IF NOT EXISTS employees (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    department VARCHAR(50),
    salary NUMERIC(10, 2),
    hire_date DATE
);
&#34;&#34;&#34;
try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.execute(create_table_query)
            # DDL (如 CREATE TABLE) 语句也需要提交
            conn.commit() 
            print(&#34;表 &#39;employees&#39; 创建成功 (如果它不存在的话)。&#34;)
except (Exception, psycopg2.DatabaseError) as error:
    print(error)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;**&lt;code&gt;conn.commit()&lt;/code&gt;*&lt;em&gt;：这是关键。任何修改数据库结构 (DDL) 或数据 (DML) 的操作，都必须调用 &lt;code&gt;conn.commit()&lt;/code&gt; 才能生效。&lt;code&gt;with conn:&lt;/code&gt; 块在&lt;/em&gt;成功退出时*会自动提交。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;B-插入数据-INSERT&#34;&gt;&lt;a href=&#34;#B-插入数据-INSERT&#34; class=&#34;headerlink&#34; title=&#34;B. 插入数据 (INSERT)&#34;&gt;&lt;/a&gt;B. 插入数据 (INSERT)&lt;/h4&gt;&lt;h5 id=&#34;插入单行&#34;&gt;&lt;a href=&#34;#插入单行&#34; class=&#34;headerlink&#34; title=&#34;插入单行&#34;&gt;&lt;/a&gt;插入单行&lt;/h5&gt;&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;query = &#34;INSERT INTO employees (name, department, salary, hire_date) VALUES (%s, %s, %s, %s)&#34;
data = (&#34;Alice Green&#34;, &#34;Engineering&#34;, 75000.00, &#34;2023-01-15&#34;)

try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.execute(query, data)
            # conn.commit() 在 with 块结束时自动调用
    print(&#34;单行插入成功。&#34;)
except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;插入失败: {error}&#34;)
    # 如果出错，with conn 块会引发异常，自动执行 conn.rollback()&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h5 id=&#34;插入多行-高效&#34;&gt;&lt;a href=&#34;#插入多行-高效&#34; class=&#34;headerlink&#34; title=&#34;插入多行 (高效)&#34;&gt;&lt;/a&gt;插入多行 (高效)&lt;/h5&gt;&lt;p&gt;使用 &lt;code&gt;cur.executemany()&lt;/code&gt; 来批量插入，这比在 &lt;code&gt;for&lt;/code&gt; 循环中调用 &lt;code&gt;execute()&lt;/code&gt; 高效得多。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;query = &#34;INSERT INTO employees (name, department, salary, hire_date) VALUES (%s, %s, %s, %s)&#34;
data_list = [
    (&#34;Bob White&#34;, &#34;Sales&#34;, 60000.00, &#34;2023-03-01&#34;),
    (&#34;Charlie Black&#34;, &#34;Engineering&#34;, 80000.00, &#34;2022-11-20&#34;),
    (&#34;David Brown&#34;, &#34;Marketing&#34;, 55000.00, &#34;2023-05-10&#34;)
]

try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.executemany(query, data_list)
            # 自动提交
    print(&#34;批量插入成功。&#34;)
except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;批量插入失败: {error}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h5 id=&#34;获取插入的-ID-RETURNING&#34;&gt;&lt;a href=&#34;#获取插入的-ID-RETURNING&#34; class=&#34;headerlink&#34; title=&#34;获取插入的 ID (RETURNING)&#34;&gt;&lt;/a&gt;获取插入的 ID (RETURNING)&lt;/h5&gt;&lt;p&gt;插入后经常需要获取新生成的 &lt;code&gt;PRIMARY KEY&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;query = &#34;INSERT INTO employees (name, department) VALUES (%s, %s) RETURNING id&#34;
data = (&#34;Eva Blue&#34;, &#34;HR&#34;)

try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.execute(query, data)
            new_id = cur.fetchone()[0] # 获取 RETURNING 的值
            print(f&#34;成功插入新员工，ID: {new_id}&#34;)
            # 自动提交
except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;插入失败: {error}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;C-查询数据-SELECT&#34;&gt;&lt;a href=&#34;#C-查询数据-SELECT&#34; class=&#34;headerlink&#34; title=&#34;C. 查询数据 (SELECT)&#34;&gt;&lt;/a&gt;C. 查询数据 (SELECT)&lt;/h4&gt;&lt;h5 id=&#34;获取单条记录-fetchone&#34;&gt;&lt;a href=&#34;#获取单条记录-fetchone&#34; class=&#34;headerlink&#34; title=&#34;获取单条记录 fetchone()&#34;&gt;&lt;/a&gt;获取单条记录 &lt;code&gt;fetchone()&lt;/code&gt;&lt;/h5&gt;&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.execute(&#34;SELECT * FROM employees WHERE department = %s&#34;, (&#34;Engineering&#34;,))

            print(&#34;正在获取一名工程师:&#34;)
            record = cur.fetchone() # 获取第一条
            if record:
                print(record) # (1, &#39;Alice Green&#39;, &#39;Engineering&#39;, 75000.00, datetime.date(2023, 1, 15))

            # 再次调用 fetchone() 会获取下一条
            record2 = cur.fetchone()
            if record2:
                print(record2)

            # 如果没有更多数据，fetchone() 返回 None
            record3 = cur.fetchone()
            print(f&#34;第三条记录: {record3}&#34;) # None

except (Exception, psycopg2.DatabaseError) as error:
    print(error)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;结果格式：&lt;/strong&gt; 默认情况下，&lt;code&gt;psycopg2&lt;/code&gt; 返回的数据是**元组 (tuple)**。&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;获取所有记录-fetchall&#34;&gt;&lt;a href=&#34;#获取所有记录-fetchall&#34; class=&#34;headerlink&#34; title=&#34;获取所有记录 fetchall()&#34;&gt;&lt;/a&gt;获取所有记录 &lt;code&gt;fetchall()&lt;/code&gt;&lt;/h5&gt;&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.execute(&#34;SELECT name, salary FROM employees WHERE salary &amp;gt; %s&#34;, (58000,))

            print(&#34;\n薪水 &amp;gt; 58000 的所有员工:&#34;)
            records = cur.fetchall() # 获取所有剩余结果

            if records:
                for row in records:
                    print(f&#34;姓名: {row[0]}, 薪水: {row[1]}&#34;)
            else:
                print(&#34;未找到记录。&#34;)

except (Exception, psycopg2.DatabaseError) as error:
    print(error)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;注意：&lt;/strong&gt; 如果结果集非常大，&lt;code&gt;fetchall()&lt;/code&gt; 可能会消耗大量内存。&lt;/li&gt;
&lt;/ul&gt;
&lt;h5 id=&#34;迭代游标-内存高效&#34;&gt;&lt;a href=&#34;#迭代游标-内存高效&#34; class=&#34;headerlink&#34; title=&#34;迭代游标 (内存高效)&#34;&gt;&lt;/a&gt;迭代游标 (内存高效)&lt;/h5&gt;&lt;p&gt;对于大数据集，最好的方式是直接迭代游标：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            # 游标充当了迭代器
            cur.execute(&#34;SELECT * FROM employees&#34;)
            print(&#34;\n--- 迭代所有员工 ---&#34;)
            for row in cur:
                print(f&#34;ID: {row[0]}, 姓名: {row[1]}&#34;)

except (Exception, psycopg2.DatabaseError) as error:
    print(error)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;D-更新数据-UPDATE&#34;&gt;&lt;a href=&#34;#D-更新数据-UPDATE&#34; class=&#34;headerlink&#34; title=&#34;D. 更新数据 (UPDATE)&#34;&gt;&lt;/a&gt;D. 更新数据 (UPDATE)&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            query = &#34;UPDATE employees SET salary = salary * 1.10 WHERE department = %s&#34;
            cur.execute(query, (&#34;Engineering&#34;,))

            # cur.rowcount 包含受影响的行数
            updated_rows = cur.rowcount
            print(f&#34;Engineering 部门 {updated_rows} 名员工已加薪。&#34;)
            # 自动提交

except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;更新失败: {error}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;E-删除数据-DELETE&#34;&gt;&lt;a href=&#34;#E-删除数据-DELETE&#34; class=&#34;headerlink&#34; title=&#34;E. 删除数据 (DELETE)&#34;&gt;&lt;/a&gt;E. 删除数据 (DELETE)&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            query = &#34;DELETE FROM employees WHERE name = %s&#34;
            cur.execute(query, (&#34;David Brown&#34;,))

            deleted_rows = cur.rowcount
            print(f&#34;成功删除 {deleted_rows} 名员工。&#34;)
            # 自动提交

except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;删除失败: {error}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;7-事务管理-Transaction&#34;&gt;&lt;a href=&#34;#7-事务管理-Transaction&#34; class=&#34;headerlink&#34; title=&#34;7. 事务管理 (Transaction)&#34;&gt;&lt;/a&gt;7. 事务管理 (Transaction)&lt;/h3&gt;&lt;p&gt;数据库事务是一组“要么全做，要么全不做”的操作。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;with psycopg2.connect(...) as conn:&lt;/code&gt; 块本身就构成了一个事务：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果 &lt;code&gt;with&lt;/code&gt; 块中的代码&lt;strong&gt;成功执行完毕&lt;/strong&gt;（没有抛出异常），&lt;code&gt;conn.commit()&lt;/code&gt; 会在块退出时自动调用。&lt;/li&gt;
&lt;li&gt;如果 &lt;code&gt;with&lt;/code&gt; 块中的代码&lt;strong&gt;抛出了异常&lt;/strong&gt;，&lt;code&gt;conn.rollback()&lt;/code&gt; 会自动调用，撤销块中已执行的所有 SQL 操作。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;示例：转账（原子操作）&lt;/strong&gt; 假设 Alice 给 Bob 转账 1000。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def transfer_money(from_id, to_id, amount):
    try:
        with psycopg2.connect(**DB_PARAMS) as conn:
            # conn 现在处于一个事务中
            with conn.cursor() as cur:

                # 1. 从 Alice 账户扣款
                cur.execute(
                    &#34;UPDATE employees SET salary = salary - %s WHERE id = %s&#34;, 
                    (amount, from_id)
                )

                # (模拟一个错误)
                # if from_id == 1:
                #     raise Exception(&#34;网络故障!&#34;)

                # 2. 向 Bob 账户加款
                cur.execute(
                    &#34;UPDATE employees SET salary = salary + %s WHERE id = %s&#34;,
                    (amount, to_id)
                )

            # 3. 退出 with conn 块，自动 commit
            print(&#34;转账成功！&#34;)

    except (Exception, psycopg2.DatabaseError) as error:
        # 4. 发生异常，自动 rollback
        print(f&#34;转账失败! 错误: {error}&#34;)
        print(&#34;事务已回滚。&#34;)

# 假设 Alice (id=1) 给 Bob (id=2) 转账 1000
transfer_money(1, 2, 1000.00) &lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;如果你取消上面“模拟一个错误”的注释，Alice 的扣款和 Bob 的加款 &lt;em&gt;都不会&lt;/em&gt; 发生，数据库将保持原样。这就是事务的威力。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;8-高级技巧&#34;&gt;&lt;a href=&#34;#8-高级技巧&#34; class=&#34;headerlink&#34; title=&#34;8. 高级技巧&#34;&gt;&lt;/a&gt;8. 高级技巧&lt;/h3&gt;&lt;h4 id=&#34;A-将结果作为字典获取-RealDictCursor&#34;&gt;&lt;a href=&#34;#A-将结果作为字典获取-RealDictCursor&#34; class=&#34;headerlink&#34; title=&#34;A. 将结果作为字典获取 (RealDictCursor)&#34;&gt;&lt;/a&gt;A. 将结果作为字典获取 (RealDictCursor)&lt;/h4&gt;&lt;p&gt;默认返回元组 &lt;code&gt;(1, &#39;Alice&#39;)&lt;/code&gt; 不太方便。我们通常想要字典 &lt;code&gt;{&#39;id&#39;: 1, &#39;name&#39;: &#39;Alice&#39;}&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;你需要导入 &lt;code&gt;psycopg2.extras&lt;/code&gt; 并指定 &lt;code&gt;cursor_factory&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;from psycopg2.extras import RealDictCursor

try:
    # 1. 在 connect 时指定 cursor_factory
    with psycopg2.connect(**DB_PARAMS, cursor_factory=RealDictCursor) as conn:

        # 2. 也可以在创建 cursor 时指定
        # with conn.cursor(cursor_factory=RealDictCursor) as cur:

        with conn.cursor() as cur: # cur 现在是 RealDictCursor
            cur.execute(&#34;SELECT id, name, salary FROM employees WHERE id = %s&#34;, (1,))
            record = cur.fetchone()

            if record:
                print(&#34;\n--- 字典游标结果 ---&#34;)
                print(record)
                # 输出: {&#39;id&#39;: 1, &#39;name&#39;: &#39;Alice Green&#39;, &#39;salary&#39;: 82500.00}
                print(f&#34;姓名: {record[&#39;name&#39;]}&#34;) # 可以通过键名访问

except (Exception, psycopg2.DatabaseError) as error:
    print(error)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;B-处理-NULL-值&#34;&gt;&lt;a href=&#34;#B-处理-NULL-值&#34; class=&#34;headerlink&#34; title=&#34;B. 处理 NULL 值&#34;&gt;&lt;/a&gt;B. 处理 &lt;code&gt;NULL&lt;/code&gt; 值&lt;/h4&gt;&lt;p&gt;&lt;code&gt;psycopg2&lt;/code&gt; 会自动处理 Python 的 &lt;code&gt;None&lt;/code&gt; 和 SQL 的 &lt;code&gt;NULL&lt;/code&gt; 之间的转换。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;这是你之前（在聊天记录中）遇到 &lt;code&gt;invalid input syntax for &#34;None&#34;&lt;/code&gt; 错误的原因：&lt;/strong&gt; 如果你使用 &lt;code&gt;f-string&lt;/code&gt; (错误方式)，&lt;code&gt;None&lt;/code&gt; 会被转成字符串 &lt;code&gt;&#34;None&#34;&lt;/code&gt;。 &lt;code&gt;INSERT ... VALUES (&#39;None&#39;)&lt;/code&gt; -&amp;gt; 数据库试图将字符串 “None” 存入 &lt;code&gt;double precision&lt;/code&gt; 字段，导致失败。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;正确方式 (使用参数化):&lt;/strong&gt; &lt;code&gt;psycopg2&lt;/code&gt; 会将 Python 的 &lt;code&gt;None&lt;/code&gt; 正确转换为 SQL 的 &lt;code&gt;NULL&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# 插入一个 hire_date 为 NULL 的记录
query = &#34;INSERT INTO employees (name, department, salary, hire_date) VALUES (%s, %s, %s, %s)&#34;
data = (&#34;Frank Nullman&#34;, &#34;IT&#34;, 62000.00, None) # Python 的 None

try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            cur.execute(query, data)
    print(&#34;成功插入带 NULL 值的记录。&#34;)
except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;插入 NULL 失败: {error}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;C-处理-JSON-JSONB-数据&#34;&gt;&lt;a href=&#34;#C-处理-JSON-JSONB-数据&#34; class=&#34;headerlink&#34; title=&#34;C. 处理 JSON/JSONB 数据&#34;&gt;&lt;/a&gt;C. 处理 &lt;code&gt;JSON/JSONB&lt;/code&gt; 数据&lt;/h4&gt;&lt;p&gt;PostgreSQ 对 &lt;code&gt;JSON&lt;/code&gt; 有很好的支持。&lt;code&gt;psycopg2&lt;/code&gt; 可以自动序列化和反序列化 Python 的 &lt;code&gt;dict&lt;/code&gt; 和 &lt;code&gt;list&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;from psycopg2.extras import Json

# 假设表有
# ALTER TABLE employees ADD COLUMN metadata JSONB;

# 写入 JSON
meta_data = {
    &#39;skills&#39;: [&#39;Python&#39;, &#39;SQL&#39;, &#39;OPC-UA&#39;],
    &#39;manager_id&#39;: 10
}

try:
    with psycopg2.connect(**DB_PARAMS) as conn:
        with conn.cursor() as cur:
            # 使用 extras.Json 包装一下
            query = &#34;UPDATE employees SET metadata = %s WHERE name = %s&#34;
            cur.execute(query, (Json(meta_data), &#34;Alice Green&#34;))

            # 读取 JSON
            cur.execute(&#34;SELECT metadata FROM employees WHERE name = %s&#34;, (&#34;Alice Green&#34;,))
            result = cur.fetchone()[0]

            print(f&#34;\n读取到的 JSONB 数据: {result}&#34;)
            print(f&#34;数据类型: {type(result)}&#34;) # &amp;lt;class &#39;dict&#39;&amp;gt;
            print(f&#34;技能: {result[&#39;skills&#39;][0]}&#34;) # &#39;Python&#39;

except (Exception, psycopg2.DatabaseError) as error:
    print(f&#34;JSON 操作失败: {error}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;9-总结：最佳实践清单&#34;&gt;&lt;a href=&#34;#9-总结：最佳实践清单&#34; class=&#34;headerlink&#34; title=&#34;9. 总结：最佳实践清单&#34;&gt;&lt;/a&gt;9. 总结：最佳实践清单&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;始终使用 &lt;code&gt;with&lt;/code&gt; 语句&lt;/strong&gt; 管理连接 (&lt;code&gt;conn&lt;/code&gt;) 和游标 (&lt;code&gt;cur&lt;/code&gt;)。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;永远使用参数化查询&lt;/strong&gt; (&lt;code&gt;cur.execute(query, (params,))&lt;/code&gt;) 来防止 SQL 注入。&lt;code&gt;%s&lt;/code&gt; 是唯一的占位符。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用 &lt;code&gt;conn.commit()&lt;/code&gt;&lt;/strong&gt; 提交更改。依赖 &lt;code&gt;with conn:&lt;/code&gt; 块的自动提交/回滚功能是最安全的方式。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用 &lt;code&gt;cur.executemany()&lt;/code&gt;&lt;/strong&gt; 进行批量插入。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用 &lt;code&gt;psycopg2.extras.RealDictCursor&lt;/code&gt;&lt;/strong&gt; 来获取字典形式的结果。&lt;/li&gt;
&lt;li&gt;**正确处理 &lt;code&gt;None&lt;/code&gt;**：参数化查询会自动将 &lt;code&gt;None&lt;/code&gt; 转为 &lt;code&gt;NULL&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;捕获 &lt;code&gt;psycopg2.DatabaseError&lt;/code&gt;&lt;/strong&gt; 来处理数据库相关的特定异常。&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;OPC-UA-与-Python-详细使用教程&#34;&gt;&lt;a href=&#34;#OPC-UA-与-Python-详细使用教程&#34; class=&#34;headerlink&#34; title=&#34;OPC-UA 与 Python 详细使用教程&#34;&gt;&lt;/a&gt;OPC-UA 与 Python 详细使用教程&lt;/h2&gt;&lt;h3 id=&#34;1-什么是-OPC-UA？&#34;&gt;&lt;a href=&#34;#1-什么是-OPC-UA？&#34; class=&#34;headerlink&#34; title=&#34;1. 什么是 OPC-UA？&#34;&gt;&lt;/a&gt;1. 什么是 OPC-UA？&lt;/h3&gt;&lt;p&gt;OPC-UA (Open Platform Communications Unified Architecture) 是一种独立于平台、面向服务的机器对机器（M2M）通信协议。它被广泛应用于工业自动化领域，用于在不同厂商的设备、控制器和软件应用之间实现安全、可靠的数据交换。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;核心概念：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;服务器 (Server):&lt;/strong&gt; 通常是设备（如 PLC、DCS）或网关，它持有数据并将其暴露给网络。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;客户端 (Client):&lt;/strong&gt; 通常是监控软件（如 SCADA、HMI）或数据采集程序，它连接到服务器以读取、写入或订阅数据。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;地址空间 (Address Space):&lt;/strong&gt; 服务器内部所有数据的分层结构。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;节点 (Node):&lt;/strong&gt; 地址空间中的一个元素，可以是对象 (Object)、变量 (Variable)、方法 (Method) 等。每个节点都有一个唯一的 &lt;code&gt;NodeId&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;变量 (Variable):&lt;/strong&gt; 存放实际数据的节点，例如温度、压力、开关状态等。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;2-安装-python-opcua&#34;&gt;&lt;a href=&#34;#2-安装-python-opcua&#34; class=&#34;headerlink&#34; title=&#34;2. 安装 python-opcua&#34;&gt;&lt;/a&gt;2. 安装 &lt;code&gt;python-opcua&lt;/code&gt;&lt;/h3&gt;&lt;p&gt;安装非常简单，使用 pip 即可：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;pip install opcua&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;3-第一部分：创建一个简单的-OPC-UA-服务器&#34;&gt;&lt;a href=&#34;#3-第一部分：创建一个简单的-OPC-UA-服务器&#34; class=&#34;headerlink&#34; title=&#34;3. 第一部分：创建一个简单的 OPC-UA 服务器&#34;&gt;&lt;/a&gt;3. 第一部分：创建一个简单的 OPC-UA 服务器&lt;/h3&gt;&lt;p&gt;我们将创建一个服务器，它会暴露一个模拟的温度传感器变量。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;import time
from opcua import ua, Server

# 1. 创建服务器实例
server = Server()

# 2. 设置服务器端点 (Endpoint)
#    客户端将通过这个 URL 连接
url = &#34;opc.tcp://0.0.0.0:4840/freeopcua/server/&#34;
server.set_endpoint(url)

# 3. 设置服务器名称（可选）
server.set_server_name(&#34;Python OPC-UA 示例服务器&#34;)

# 4. 设置安全策略（这里使用最不安全的，方便测试）
#    实际应用中应使用更安全的策略
server.set_security_policy([
    ua.SecurityPolicyType.NoSecurity,
    ua.SecurityPolicyType.Basic256Sha256_SignAndEncrypt,
    ua.SecurityPolicyType.Basic256Sha256_Sign
])

# 5. 注册一个唯一的命名空间 (Namespace)
#    命名空间用于组织你自己的节点，防止与标准节点冲突
ns_name = &#34;http://examples.freeopcua.github.io&#34;
idx = server.register_namespace(ns_name)

# 6. 在服务器的 Objects 节点下创建一个“MyObjects”文件夹
objects = server.get_objects_node()
my_folder = objects.add_object(idx, &#34;MyObjects&#34;)

# 7. 在“MyObjects”文件夹下创建变量
#    idx: 命名空间索引
#    &#34;MyVariable&#34;: 节点的浏览名称 (BrowseName)
#    0: 变量的初始值
my_var = my_folder.add_variable(idx, &#34;MyVariable&#34;, 0)
my_temp_sensor = my_folder.add_variable(idx, &#34;TemperatureSensor&#34;, 20.0)

# 8. 使变量可被客户端写入
#    默认情况下，变量是只读的
my_var.set_writable()
my_temp_sensor.set_writable()

# 9. 启动服务器
try:
    print(f&#34;启动服务器于 {url}&#34;)
    server.start()

    # 让服务器持续运行，并模拟温度变化
    temperature = 20.0
    delta = 0.5

    while True:
        time.sleep(2)  # 每2秒更新一次

        temperature += delta
        if temperature &amp;gt; 30 or temperature &amp;lt; 19:
            delta = -delta # 调转方向

        print(f&#34;设置新温度值为: {temperature:.1f}&#34;)
        my_temp_sensor.set_value(temperature)

except KeyboardInterrupt:
    print(&#34;\n服务器正在停止...&#34;)
finally:
    # 10. 关闭服务器
    server.stop()
    print(&#34;服务器已关闭&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;运行：&lt;/strong&gt; 将以上代码保存为 &lt;code&gt;server.py&lt;/code&gt; 并运行 &lt;code&gt;python server.py&lt;/code&gt;。你现在就有了一个正在运行的 OPC-UA 服务器。&lt;/p&gt;
&lt;h3 id=&#34;4-第二部分：创建一个-OPC-UA-客户端（读写）&#34;&gt;&lt;a href=&#34;#4-第二部分：创建一个-OPC-UA-客户端（读写）&#34; class=&#34;headerlink&#34; title=&#34;4. 第二部分：创建一个 OPC-UA 客户端（读写）&#34;&gt;&lt;/a&gt;4. 第二部分：创建一个 OPC-UA 客户端（读写）&lt;/h3&gt;&lt;p&gt;现在我们创建另一个脚本来连接服务器、读取和写入数据。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;import time
from opcua import Client, ua

# 服务器的 URL，与 server.py 中设置的保持一致
url = &#34;opc.tcp://localhost:4840/freeopcua/server/&#34;

# 1. 创建客户端实例
client = Client(url)

try:
    # 2. 连接到服务器
    print(f&#34;正在连接到 {url} ...&#34;)
    client.connect()
    print(&#34;连接成功！&#34;)

    # 3. 浏览节点 (可选, 但有助于理解结构)
    #    获取根节点
    root = client.get_root_node()
    print(f&#34;根节点: {root}&#34;)
    print(f&#34;根节点的子节点: {root.get_children()}&#34;)

    # 4. 获取我们感兴趣的特定节点
    #    方法a: 通过浏览路径 (Browse Path)
    #    路径: Root -&amp;gt; Objects (0:Objects) -&amp;gt; 命名空间2 (2:MyObjects) -&amp;gt; 变量 (2:TemperatureSensor)
    #    &#39;2&#39; 是我们自己注册的命名空间的索引 (idx)
    #    注意: 命名空间索引 (ns) 可能会变化，通常 0 是标准，1 是服务器内部，我们注册的从 2 开始
    temp_node = client.get_node(&#34;ns=2;s=TemperatureSensor&#34;)
    my_var_node = client.get_node(&#34;ns=2;s=MyVariable&#34;)

    #    方法b: 通过 NodeId (如果已知)
    #    node_id_str = &#34;ns=2;i=2&#34; # 假设你知道它的 NodeId
    #    temp_node = client.get_node(node_id_str)

    print(&#34;-&#34; * 30)

    # 5. 读取节点的值
    current_temp = temp_node.get_value()
    print(f&#34;读取到当前温度: {current_temp}&#34;)

    current_var = my_var_node.get_value()
    print(f&#34;读取到 MyVariable: {current_var}&#34;)

    print(&#34;-&#34; * 30)

    # 6. 写入节点的值
    new_value = 99.9
    print(f&#34;正在向 MyVariable 写入新值: {new_value}&#34;)

    # 构造 ua.DataValue 和 ua.Variant
    data_value = ua.DataValue(ua.Variant(new_value, ua.VariantType.Double))
    my_var_node.set_value(data_value)

    # 验证写入
    time.sleep(1)
    read_back = my_var_node.get_value()
    print(f&#34;回读 MyVariable 的值: {read_back}&#34;)

    # 尝试写入只读节点（如果 TemperatureSensor 没设置 set_writable()，这里会报错）
    try:
        temp_node.set_value(ua.DataValue(ua.Variant(100.0, ua.VariantType.Float)))
        print(&#34;成功写入温度值 (服务器端允许写入)&#34;)
    except ua.UaError as e:
        print(f&#34;写入温度值失败 (可能是只读): {e}&#34;)


finally:
    # 7. 断开连接
    if client:
        client.disconnect()
        print(&#34;客户端已断开连接&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;运行：&lt;/strong&gt; 保持 &lt;code&gt;server.py&lt;/code&gt; 运行，打开一个新的终端，运行 &lt;code&gt;python client.py&lt;/code&gt;。你将看到客户端连接、读取、写入并断开连接的过程。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;5-第三部分：订阅数据变化&#34;&gt;&lt;a href=&#34;#5-第三部分：订阅数据变化&#34; class=&#34;headerlink&#34; title=&#34;5. 第三部分：订阅数据变化&#34;&gt;&lt;/a&gt;5. 第三部分：订阅数据变化&lt;/h3&gt;&lt;p&gt;OPC-UA 最强大的功能之一是订阅。客户端不需要（也不应该）频繁轮询数据，而是可以告诉服务器：“当这个变量变化时，请通知我。”&lt;/p&gt;
&lt;p&gt;我们将修改客户端代码来实现订阅。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;import time
from opcua import Client

# 1. 定义一个订阅处理器类 (Handler)
class SubHandler(object):
    &#34;&#34;&#34;
    订阅处理器，用于处理来自服务器的数据变更通知。
    &#34;&#34;&#34;
    def datachange_notification(self, node, val, data):
        &#34;&#34;&#34;
        当订阅的节点数据发生变化时，此方法被调用。
        &#34;&#34;&#34;
        print(f&#34;[订阅] 节点 {node} 的值变为: {val}&#34;)

    def event_notification(self, event):
        &#34;&#34;&#34;
        处理事件通知 (本例中未使用)
        &#34;&#34;&#34;
        print(f&#34;[订阅] 收到新事件: {event}&#34;)

# --- 主程序 ---
url = &#34;opc.tcp://localhost:4840/freeopcua/server/&#34;
client = Client(url)

try:
    client.connect()
    print(&#34;客户端已连接&#34;)

    # 2. 获取要订阅的节点
    temp_node = client.get_node(&#34;ns=2;s=TemperatureSensor&#34;)
    print(f&#34;将要订阅的节点: {temp_node}&#34;)

    # 3. 创建订阅处理器实例
    handler = SubHandler()

    # 4. 在客户端上创建订阅 (Subscription)
    #    参数 1000: 订阅的发布间隔 (ms)。服务器将每1000ms检查一次是否有变化。
    subscription = client.create_subscription(1000, handler)
    print(&#34;已创建订阅&#34;)

    # 5. 告诉订阅要监控哪个节点 (MonitoredItem)
    #    参数 10: 队列大小 (QueueSize)
    handle = subscription.subscribe_data_change(temp_node, queuesize=10)
    print(f&#34;已订阅节点 {temp_node} 的数据变化&#34;)

    # 6. 让客户端保持运行以接收通知
    print(&#34;正在等待数据变化 (按 Ctrl+C 停止)...&#34;)
    while True:
        time.sleep(1)

except KeyboardInterrupt:
    print(&#34;\n正在停止订阅...&#34;)
finally:
    # 7. 删除订阅 (可选, 但良好实践)
    if &#39;subscription&#39; in locals():
        subscription.delete()
        print(&#34;订阅已删除&#34;)

    # 8. 断开连接
    client.disconnect()
    print(&#34;客户端已断开&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;运行：&lt;/strong&gt; 确保 &lt;code&gt;server.py&lt;/code&gt; 正在运行（它会每2秒更新一次温度）。然后运行这个新的订阅客户端脚本 &lt;code&gt;subscriber.py&lt;/code&gt;。你将看到它每2秒（或根据服务器的更新频率）打印一次 &lt;code&gt;[订阅] ...&lt;/code&gt; 的消息。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;6-第四部分：在服务器上创建并调用方法&#34;&gt;&lt;a href=&#34;#6-第四部分：在服务器上创建并调用方法&#34; class=&#34;headerlink&#34; title=&#34;6. 第四部分：在服务器上创建并调用方法&#34;&gt;&lt;/a&gt;6. 第四部分：在服务器上创建并调用方法&lt;/h3&gt;&lt;p&gt;OPC-UA 不仅能传输数据，还能执行命令（方法）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 修改 &lt;code&gt;server.py&lt;/code&gt;：&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在 &lt;code&gt;server.start()&lt;/code&gt; 之前，添加以下代码来定义一个方法：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# --- (接第 8 步之后, server.start() 之前) ---

# 定义一个 Python 函数作为方法的实现
def multiply_by_two(parent, variant_x):
    &#34;&#34;&#34;
    一个简单的 OPC-UA 方法，接收一个输入参数并返回其两倍。
    &#34;&#34;&#34;
    x = variant_x.Value
    print(f&#34;服务器方法 &#39;multiply_by_two&#39; 被调用，输入: {x}&#34;)

    result = x * 2

    # 返回值必须是 ua.Variant
    return [ua.Variant(result, ua.VariantType.Double)]

# 9. 在 &#34;MyObjects&#34; 文件夹下注册这个方法
#    输入参数定义
in_arg = ua.Argument()
in_arg.Name = &#34;InputX&#34;
in_arg.DataType = ua.NodeId(ua.ObjectIds.Double)
in_arg.ValueRank = -1
in_arg.ArrayDimensions = []
in_arg.Description = ua.LocalizedText(&#34;一个浮点数输入&#34;)

# 输出参数定义
out_arg = ua.Argument()
out_arg.Name = &#34;ResultY&#34;
out_arg.DataType = ua.NodeId(ua.ObjectIds.Double)
out_arg.ValueRank = -1
out_arg.ArrayDimensions = []
out_arg.Description = ua.LocalizedText(&#34;返回 InputX * 2&#34;)

# 将方法添加到地址空间
my_folder.add_method(
    idx,                          # 命名空间
    &#34;MultiplyByTwo&#34;,              # 方法名称
    multiply_by_two,              # 绑定的 Python 函数
    [in_arg],                     # 输入参数列表
    [out_arg]                     # 输出参数列表
)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;2. 修改 &lt;code&gt;client.py&lt;/code&gt;（普通的读写客户端）：&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在 &lt;code&gt;client.disconnect()&lt;/code&gt; 之前，添加以下代码来调用该方法：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# --- (接第 6 步之后, client.disconnect() 之前) ---

print(&#34;-&#34; * 30)
# 7. 调用服务器上的方法
print(&#34;正在调用服务器方法 &#39;MultiplyByTwo&#39;...&#34;)

# 获取方法节点
method_node = my_folder_node.get_child(&#34;2:MultiplyByTwo&#34;)

# 准备输入参数
input_value = 10.5
print(f&#34;输入参数为: {input_value}&#34;)

# 调用方法 (父节点, 方法节点, 输入参数)
# 父节点是 &#39;MyObjects&#39;
my_folder_node = client.get_node(&#34;ns=2;s=MyObjects&#34;) 
result = my_folder_node.call_method(method_node, input_value)
# 或者: result = client.call_method(method_node, input_value) 

print(f&#34;服务器返回结果: {result}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;em&gt;注意：&lt;/em&gt; 你需要先在客户端代码中获取 &lt;code&gt;my_folder_node&lt;/code&gt;，例如 &lt;code&gt;my_folder_node = client.get_node(&#34;ns=2;s=MyObjects&#34;)&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;运行：&lt;/strong&gt; 重启服务器 &lt;code&gt;server.py&lt;/code&gt;（现在它包含了方法）。运行 &lt;code&gt;client.py&lt;/code&gt;，你将看到客户端成功调用了服务器上的 &lt;code&gt;MultiplyByTwo&lt;/code&gt; 方法并获得了 &lt;code&gt;21.0&lt;/code&gt; 的返回结果。&lt;/p&gt;
&lt;h3 id=&#34;总结&#34;&gt;&lt;a href=&#34;#总结&#34; class=&#34;headerlink&#34; title=&#34;总结&#34;&gt;&lt;/a&gt;总结&lt;/h3&gt;&lt;p&gt;本教程涵盖了 &lt;code&gt;python-opcua&lt;/code&gt; 最核心的三个功能：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;创建服务器&lt;/strong&gt; 并暴露变量。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;创建客户端&lt;/strong&gt; 以读取和写入变量。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用订阅&lt;/strong&gt; 来实时接收数据变更通知。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用方法&lt;/strong&gt; 来执行远程命令。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;在实际应用中，你还需要深入了解：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;安全性：&lt;/strong&gt; 使用证书和用户认证来保护你的服务器。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;复杂数据类型：&lt;/strong&gt; 定义和使用自定义的结构体 (Structs)。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;历史数据：&lt;/strong&gt; 查询历史数据 (Historical Access)。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;事件 (Events)：&lt;/strong&gt; 订阅比数据变更更复杂的事件（如警报）。&lt;/li&gt;
&lt;/ul&gt;

 &lt;h1 id=&#34;在WSL中将-python3-命令别名为-python&#34;&gt;&lt;a href=&#34;#在WSL中将-python3-命令别名为-python&#34; class=&#34;headerlink&#34; title=&#34;在WSL中将 python3 命令别名为 python&#34;&gt;&lt;/a&gt;在WSL中将 &lt;code&gt;python3&lt;/code&gt; 命令别名为 &lt;code&gt;python&lt;/code&gt;&lt;/h1&gt;&lt;p&gt;在 Windows Subsystem for Linux (WSL) 环境中，默认情况下，Python 3.x 版本通常通过 &lt;code&gt;python3&lt;/code&gt; 命令调用，而 &lt;code&gt;python&lt;/code&gt; 命令可能未定义或指向老旧的 Python 2.x 版本。为了方便起见，您可以将 &lt;code&gt;python3&lt;/code&gt; 命令别名为 &lt;code&gt;python&lt;/code&gt;，从而直接使用 &lt;code&gt;python&lt;/code&gt; 命令来执行 Python 3.x。&lt;/p&gt;
&lt;p&gt;最常用且推荐的方法是创建一个永久性的别名，这通过修改您 shell 的配置文件（通常是 &lt;code&gt;.bashrc&lt;/code&gt;）来实现。这样，每次启动新的 WSL 终端时，该别名都会自动生效。&lt;/p&gt;
&lt;p&gt;以下是详细的步骤：&lt;/p&gt;
&lt;h3 id=&#34;1-打开您的-shell-配置文件&#34;&gt;&lt;a href=&#34;#1-打开您的-shell-配置文件&#34; class=&#34;headerlink&#34; title=&#34;1. 打开您的 shell 配置文件&#34;&gt;&lt;/a&gt;1. 打开您的 shell 配置文件&lt;/h3&gt;&lt;p&gt;您需要使用一个命令行文本编辑器（如 &lt;code&gt;nano&lt;/code&gt;、&lt;code&gt;vim&lt;/code&gt; 或 &lt;code&gt;emacs&lt;/code&gt;）来编辑位于您用户主目录下的 &lt;code&gt;.bashrc&lt;/code&gt; 文件。对于大多数用户来说，默认的 shell 是 Bash。&lt;/p&gt;
&lt;p&gt;打开终端并输入以下命令：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;nano&lt;/span&gt; ~/.bashrc&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;如果您使用的是 Zsh，则应编辑 &lt;code&gt;.zshrc&lt;/code&gt; 文件：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;nano&lt;/span&gt; ~/.zshrc&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;2-添加别名设置&#34;&gt;&lt;a href=&#34;#2-添加别名设置&#34; class=&#34;headerlink&#34; title=&#34;2. 添加别名设置&#34;&gt;&lt;/a&gt;2. 添加别名设置&lt;/h3&gt;&lt;p&gt;在打开的文件中，滚动到文件末尾，并添加以下这行代码：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token builtin class-name&#34;&gt;alias&lt;/span&gt; &lt;span class=&#34;token assign-left variable&#34;&gt;python&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;python3&#39;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;这一行代码的作用是告诉 shell，当您输入 &lt;code&gt;python&lt;/code&gt; 时，实际上应该执行 &lt;code&gt;python3&lt;/code&gt; 命令。&lt;/p&gt;
&lt;p&gt;您还可以选择为 &lt;code&gt;pip&lt;/code&gt; 创建一个类似的别名：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token builtin class-name&#34;&gt;alias&lt;/span&gt; &lt;span class=&#34;token assign-left variable&#34;&gt;pip&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;pip3&#39;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;3-保存并关闭文件&#34;&gt;&lt;a href=&#34;#3-保存并关闭文件&#34; class=&#34;headerlink&#34; title=&#34;3. 保存并关闭文件&#34;&gt;&lt;/a&gt;3. 保存并关闭文件&lt;/h3&gt;&lt;p&gt;如果您使用的是 &lt;code&gt;nano&lt;/code&gt; 编辑器，请按 &lt;code&gt;Ctrl + O&lt;/code&gt; 来保存文件，然后按 &lt;code&gt;Enter&lt;/code&gt; 确认。接着按 &lt;code&gt;Ctrl + X&lt;/code&gt; 退出编辑器。&lt;/p&gt;
&lt;h3 id=&#34;4-使更改生效&#34;&gt;&lt;a href=&#34;#4-使更改生效&#34; class=&#34;headerlink&#34; title=&#34;4. 使更改生效&#34;&gt;&lt;/a&gt;4. 使更改生效&lt;/h3&gt;&lt;p&gt;新添加的别名不会立即在当前的终端会话中生效。您需要让 shell 重新加载配置文件。您可以通过以下任一方式实现：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;关闭并重新打开您的 WSL 终端。&lt;/strong&gt; 这是最简单直接的方法。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;在当前终端会话中执行以下命令：&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token builtin class-name&#34;&gt;source&lt;/span&gt; ~/.bashrc&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;或者，如果您使用的是 Zsh：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token builtin class-name&#34;&gt;source&lt;/span&gt; ~/.zshrc&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;5-验证别名是否生效&#34;&gt;&lt;a href=&#34;#5-验证别名是否生效&#34; class=&#34;headerlink&#34; title=&#34;5. 验证别名是否生效&#34;&gt;&lt;/a&gt;5. 验证别名是否生效&lt;/h3&gt;&lt;p&gt;现在，您可以在终端中输入以下命令来验证 &lt;code&gt;python&lt;/code&gt; 命令是否已成功指向 Python 3：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;python &lt;span class=&#34;token parameter variable&#34;&gt;--version&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;如果一切顺利，输出结果应该显示您的 Python 3.x 版本号，例如：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;Python &lt;span class=&#34;token number&#34;&gt;3.10&lt;/span&gt;.6&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;通过以上步骤，您已经成功地在 WSL 中将 &lt;code&gt;python3&lt;/code&gt; 命令别名为 &lt;code&gt;python&lt;/code&gt;，这将为您在开发过程中提供更便捷的体验。&lt;/p&gt;

 &lt;h1 id=&#34;Python-包管理与导入全方位教程&#34;&gt;&lt;a href=&#34;#Python-包管理与导入全方位教程&#34; class=&#34;headerlink&#34; title=&#34;Python 包管理与导入全方位教程&#34;&gt;&lt;/a&gt;Python 包管理与导入全方位教程&lt;/h1&gt;&lt;p&gt;在 Python 开发中，代码的组织、复用和分发都离不开模块（Module）和包（Package）。掌握好它们的导入机制以及如何管理项目依赖，是从新手走向专业的必经之路。&lt;/p&gt;
&lt;p&gt;本教程将涵盖四个核心部分：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;模块与导入：基础篇&lt;/strong&gt; - 理解 Python 如何导入单个文件。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;包的创建与内部导入：进阶篇&lt;/strong&gt; - 如何组织你自己的项目代码。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用 &lt;code&gt;pip&lt;/code&gt; 管理外部包：工具篇&lt;/strong&gt; - 如何安装和使用社区的优秀代码。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;虚拟环境：最佳实践&lt;/strong&gt; - 为什么需要以及如何使用虚拟环境来隔离项目。&lt;/li&gt;
&lt;/ol&gt;
&lt;hr&gt;
&lt;h3 id=&#34;Part-1-模块与导入：基础篇&#34;&gt;&lt;a href=&#34;#Part-1-模块与导入：基础篇&#34; class=&#34;headerlink&#34; title=&#34;Part 1: 模块与导入：基础篇&#34;&gt;&lt;/a&gt;Part 1: 模块与导入：基础篇&lt;/h3&gt;&lt;h4 id=&#34;1-1-什么是模块-Module-？&#34;&gt;&lt;a href=&#34;#1-1-什么是模块-Module-？&#34; class=&#34;headerlink&#34; title=&#34;1.1 什么是模块 (Module)？&#34;&gt;&lt;/a&gt;1.1 什么是模块 (Module)？&lt;/h4&gt;&lt;p&gt;在 Python 中，&lt;strong&gt;任何一个 &lt;code&gt;.py&lt;/code&gt; 文件都可以被看作一个模块&lt;/strong&gt;。模块能让你将相关的代码（函数、类、变量）组织在一起，方便在其他地方复用。&lt;/p&gt;
&lt;p&gt;例如，我们创建一个 &lt;code&gt;math_utils.py&lt;/code&gt; 文件：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# math_utils.py
PI = 3.14159

def add(a, b):
    return a + b

class Circle:
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return PI * self.radius * self.radius&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;1-2-import-语句的基本用法&#34;&gt;&lt;a href=&#34;#1-2-import-语句的基本用法&#34; class=&#34;headerlink&#34; title=&#34;1.2 import 语句的基本用法&#34;&gt;&lt;/a&gt;1.2 &lt;code&gt;import&lt;/code&gt; 语句的基本用法&lt;/h4&gt;&lt;p&gt;&lt;code&gt;import&lt;/code&gt; 语句用于将其他模块的功能引入到当前文件中。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;方式一：导入整个模块&lt;/strong&gt; 这是最常见的方式。你需要通过 &lt;code&gt;模块名.&lt;/code&gt; 的前缀来访问其内容。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# main.py
import math_utils

print(math_utils.PI)  # 输出: 3.14159

sum_result = math_utils.add(3, 5)
print(sum_result) # 输出: 8

my_circle = math_utils.Circle(10)
print(my_circle.area()) # 输出: 314.159&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;方式二：使用 &lt;code&gt;as&lt;/code&gt; 设置别名&lt;/strong&gt; 如果模块名太长或者容易混淆，可以给它设置一个简短的别名。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;import math_utils as mu

print(mu.PI)
print(mu.add(3, 5))&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;方式三：使用 &lt;code&gt;from...import...&lt;/code&gt; 导入特定内容&lt;/strong&gt; 如果你只需要模块中的某几个部分，可以使用 &lt;code&gt;from&lt;/code&gt; 关键字直接导入它们。这样，在使用时就不需要加模块名前缀了。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;from math_utils import add, Circle

sum_result = add(4, 6) # 直接调用 add，无需前缀
print(sum_result) # 输出: 10

my_circle = Circle(5)
print(my_circle.area()) # 输出: 78.53975&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;也可以为导入的特定内容设置别名：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;from math_utils import add as sum_func

result = sum_func(1, 2)
print(result) # 输出: 3&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;方式四：&lt;code&gt;from...import \*&lt;/code&gt;（不推荐）&lt;/strong&gt; 这会导入模块中所有非下划线开头的内容。&lt;strong&gt;强烈不推荐&lt;/strong&gt;在大型项目中使用，因为它会污染当前文件的命名空间，你可能不知道哪些函数和变量被导入了，容易导致名称冲突和代码可读性下降。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# 谨慎使用！
from math_utils import *

print(PI) # 直接可用
print(add(1, 1)) # 直接可用&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;Part-2-包的创建与内部导入：进阶篇&#34;&gt;&lt;a href=&#34;#Part-2-包的创建与内部导入：进阶篇&#34; class=&#34;headerlink&#34; title=&#34;Part 2: 包的创建与内部导入：进阶篇&#34;&gt;&lt;/a&gt;Part 2: 包的创建与内部导入：进阶篇&lt;/h3&gt;&lt;p&gt;当项目变得复杂，一个文件已经不够用时，我们就需要用“包”（Package）来组织模块。&lt;/p&gt;
&lt;h4 id=&#34;2-1-什么是包-Package-？&#34;&gt;&lt;a href=&#34;#2-1-什么是包-Package-？&#34; class=&#34;headerlink&#34; title=&#34;2.1 什么是包 (Package)？&#34;&gt;&lt;/a&gt;2.1 什么是包 (Package)？&lt;/h4&gt;&lt;p&gt;简单来说，&lt;strong&gt;一个包含 &lt;code&gt;__init__.py&lt;/code&gt; 文件的目录就是一个包&lt;/strong&gt;。这个目录里可以存放多个模块（&lt;code&gt;.py&lt;/code&gt; 文件）或者子包。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;__init__.py&lt;/code&gt; 文件有几个作用：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;标记作用&lt;/strong&gt;：它的存在告诉 Python 这个目录应该被当作一个包来对待。在 Python 3.3+ 版本中，即使没有这个文件，也可能被当作“命名空间包”，但为了兼容性和清晰性，&lt;strong&gt;强烈建议总是创建它&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;初始化操作&lt;/strong&gt;：可以在这个文件中编写代码，当包被导入时，这些代码会自动执行。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;简化导入&lt;/strong&gt;：可以在 &lt;code&gt;__init__.py&lt;/code&gt; 中使用 &lt;code&gt;from .module import func&lt;/code&gt; 的方式，将包深处的函数或类暴露到包的顶层，方便外部调用。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;2-2-项目结构示例&#34;&gt;&lt;a href=&#34;#2-2-项目结构示例&#34; class=&#34;headerlink&#34; title=&#34;2.2 项目结构示例&#34;&gt;&lt;/a&gt;2.2 项目结构示例&lt;/h4&gt;&lt;p&gt;让我们构建一个清晰的项目结构作为例子：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;my_project/
├── main.py             &lt;span class=&#34;token comment&#34;&gt;# 项目主入口文件&lt;/span&gt;
└── my_app/             &lt;span class=&#34;token comment&#34;&gt;# 我们的主应用包&lt;/span&gt;
    ├── __init__.py
    ├── core/           &lt;span class=&#34;token comment&#34;&gt;# 子包：核心功能&lt;/span&gt;
    │   ├── __init__.py
    │   └── calculator.py
    └── utils/          &lt;span class=&#34;token comment&#34;&gt;# 子包：工具函数&lt;/span&gt;
        ├── __init__.py
        └── formatter.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;calculator.py&lt;/code&gt; 内容:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# my_app/core/calculator.py
def add(a, b):
    return a + b&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;formatter.py&lt;/code&gt; 内容:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# my_app/utils/formatter.py
def format_as_json(data):
    # 这是一个简化的例子
    return f&#39;{{&#34;result&#34;: {data}}}&#39;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;2-3-包内导入：绝对导入-vs-相对导入&#34;&gt;&lt;a href=&#34;#2-3-包内导入：绝对导入-vs-相对导入&#34; class=&#34;headerlink&#34; title=&#34;2.3 包内导入：绝对导入 vs 相对导入&#34;&gt;&lt;/a&gt;2.3 包内导入：绝对导入 vs 相对导入&lt;/h4&gt;&lt;p&gt;现在，假设我们想在 &lt;code&gt;calculator.py&lt;/code&gt; 中使用 &lt;code&gt;formatter.py&lt;/code&gt; 的功能（虽然这个例子不太合逻辑，但很适合演示）。这就要用到包内导入。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 绝对导入 (Absolute Import) - 推荐&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;绝对导入总是从项目的&lt;strong&gt;根目录&lt;/strong&gt;（可以被 Python 找到的路径，通常是你运行命令的目录）开始。它路径清晰，不容易出错，是 PEP 8 规范推荐的方式。&lt;/p&gt;
&lt;p&gt;假设我们在 &lt;code&gt;main.py&lt;/code&gt; 中想使用 &lt;code&gt;calculator&lt;/code&gt; 和 &lt;code&gt;formatter&lt;/code&gt;：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# main.py
from my_app.core import calculator
from my_app.utils import formatter

result = calculator.add(10, 20)
print(formatter.format_as_json(result))
# 输出: {&#34;result&#34;: 30}&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;2. 相对导入 (Relative Import)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;相对导入使用 &lt;code&gt;.&lt;/code&gt; 或 &lt;code&gt;..&lt;/code&gt; 来表示相对位置，它&lt;strong&gt;只能在包内部使用&lt;/strong&gt;，不能在顶级脚本中使用。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;.&lt;/code&gt;：表示当前目录。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;..&lt;/code&gt;：表示上级目录。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;现在，假设我们的 &lt;code&gt;calculator.py&lt;/code&gt; 需要调用 &lt;code&gt;formatter.py&lt;/code&gt;。这在不同目录，&lt;code&gt;calculator.py&lt;/code&gt; 需要先回到父级目录 &lt;code&gt;my_app&lt;/code&gt;，再进入 &lt;code&gt;utils&lt;/code&gt; 目录。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# my_app/core/calculator.py

# &#39;..&#39; 代表回到 calculator.py 的上级目录 (core -&amp;gt; my_app)
# 然后从 my_app 进入 utils 包，导入 formatter 模块
from ..utils import formatter

def add_and_format(a, b):
    sum_val = a + b
    return formatter.format_as_json(sum_val)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;⚠️ 常见的陷阱：&lt;code&gt;ImportError&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;如果你直接运行一个使用了相对导入的文件，就会触发 &lt;code&gt;ImportError: attempted relative import with no known parent package&lt;/code&gt; 错误。&lt;/p&gt;
&lt;p&gt;例如，直接在终端里运行： &lt;code&gt;python my_app/core/calculator.py&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;这会失败！因为 Python 将 &lt;code&gt;calculator.py&lt;/code&gt; 当作顶级脚本，它不知道自己的“父包”是谁。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;正确的运行方式&lt;/strong&gt;是从项目的根目录 &lt;code&gt;my_project/&lt;/code&gt; 执行：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;如果你要运行 main.py（它使用绝对导入），直接运行即可：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;cd my_project/
python main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;如果你想把某个子模块当作脚本运行（例如测试），请使用 -m 标志：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;cd my_project/
python -m my_app.core.calculator&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h3 id=&#34;Part-3-使用-pip-管理外部包：工具篇&#34;&gt;&lt;a href=&#34;#Part-3-使用-pip-管理外部包：工具篇&#34; class=&#34;headerlink&#34; title=&#34;Part 3: 使用 pip 管理外部包：工具篇&#34;&gt;&lt;/a&gt;Part 3: 使用 &lt;code&gt;pip&lt;/code&gt; 管理外部包：工具篇&lt;/h3&gt;&lt;p&gt;当项目需要用到第三方库（如 &lt;code&gt;requests&lt;/code&gt; 用于网络请求，&lt;code&gt;pandas&lt;/code&gt; 用于数据分析）时，就需要包管理器。Python 的标准包管理器是 &lt;code&gt;pip&lt;/code&gt;。&lt;/p&gt;
&lt;h4 id=&#34;3-1-pip-基础命令&#34;&gt;&lt;a href=&#34;#3-1-pip-基础命令&#34; class=&#34;headerlink&#34; title=&#34;3.1 pip 基础命令&#34;&gt;&lt;/a&gt;3.1 &lt;code&gt;pip&lt;/code&gt; 基础命令&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;安装包&lt;/strong&gt;:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;pip install requests&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;安装指定版本的包&lt;/strong&gt;:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;pip install requests==2.28.1
pip install &#34;requests&amp;gt;=2.25.0&#34;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;卸载包&lt;/strong&gt;:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip uninstall requests&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;查看已安装的包&lt;/strong&gt;:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip list&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;查看某个包的详细信息&lt;/strong&gt;:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip show requests&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;3-2-使用-requirements-txt-管理项目依赖&#34;&gt;&lt;a href=&#34;#3-2-使用-requirements-txt-管理项目依赖&#34; class=&#34;headerlink&#34; title=&#34;3.2 使用 requirements.txt 管理项目依赖&#34;&gt;&lt;/a&gt;3.2 使用 &lt;code&gt;requirements.txt&lt;/code&gt; 管理项目依赖&lt;/h4&gt;&lt;p&gt;当你的项目依赖多个包，或者你需要与他人协作时，手动一个一个安装包是不可行的。最佳实践是使用 &lt;code&gt;requirements.txt&lt;/code&gt; 文件来记录所有依赖。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;生成 &lt;code&gt;requirements.txt&lt;/code&gt;&lt;/strong&gt;: 当你完成开发，将当前环境中所有包及其版本信息冻结（freeze）到一个文件中：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip freeze &lt;span class=&#34;token operator&#34;&gt;&amp;gt;&lt;/span&gt; requirements.txt&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;文件内容可能如下：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token assign-left variable&#34;&gt;certifi&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2022.9&lt;/span&gt;.24
charset-normalizer&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2.1&lt;/span&gt;.1
&lt;span class=&#34;token assign-left variable&#34;&gt;idna&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;3.4&lt;/span&gt;
&lt;span class=&#34;token assign-left variable&#34;&gt;requests&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2.28&lt;/span&gt;.1
&lt;span class=&#34;token assign-left variable&#34;&gt;urllib3&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1.26&lt;/span&gt;.12&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;从 &lt;code&gt;requirements.txt&lt;/code&gt; 安装&lt;/strong&gt;: 当另一个开发者拿到你的项目后，只需一条命令就可以安装所有必需的依赖：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-r&lt;/span&gt; requirements.txt&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;hr&gt;
&lt;h3 id=&#34;Part-4-虚拟环境：最佳实践&#34;&gt;&lt;a href=&#34;#Part-4-虚拟环境：最佳实践&#34; class=&#34;headerlink&#34; title=&#34;Part 4: 虚拟环境：最佳实践&#34;&gt;&lt;/a&gt;Part 4: 虚拟环境：最佳实践&lt;/h3&gt;&lt;h4 id=&#34;4-1-为什么需要虚拟环境？&#34;&gt;&lt;a href=&#34;#4-1-为什么需要虚拟环境？&#34; class=&#34;headerlink&#34; title=&#34;4.1 为什么需要虚拟环境？&#34;&gt;&lt;/a&gt;4.1 为什么需要虚拟环境？&lt;/h4&gt;&lt;p&gt;想象一下：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;项目 A 需要 &lt;code&gt;requests&lt;/code&gt; 的 1.0 版本。&lt;/li&gt;
&lt;li&gt;项目 B 需要 &lt;code&gt;requests&lt;/code&gt; 的 2.0 版本。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;如果你将它们都安装在全局的 Python环境中，就会产生版本冲突，导致一个项目无法正常工作。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;虚拟环境（Virtual Environment）&lt;/strong&gt; 就是为了解决这个问题而生的。它能为每个项目创建一个独立的、隔离的 Python 环境。你在其中安装的所有包都只属于这个项目，不会影响到全局环境或其他项目。&lt;/p&gt;
&lt;h4 id=&#34;4-2-使用-venv（Python-内置工具）&#34;&gt;&lt;a href=&#34;#4-2-使用-venv（Python-内置工具）&#34; class=&#34;headerlink&#34; title=&#34;4.2 使用 venv（Python 内置工具）&#34;&gt;&lt;/a&gt;4.2 使用 &lt;code&gt;venv&lt;/code&gt;（Python 内置工具）&lt;/h4&gt;&lt;p&gt;从 Python 3.3 开始，&lt;code&gt;venv&lt;/code&gt; 模块成为创建虚拟环境的标准工具。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 创建虚拟环境&lt;/strong&gt;: 在你的项目根目录下，运行以下命令。&lt;code&gt;venv&lt;/code&gt; 是你给这个环境起的名字，这是一个通用惯例。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;# 在 my_project/ 目录下
python -m venv venv&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;执行后，会创建一个 &lt;code&gt;venv&lt;/code&gt; 目录，里面包含了独立的 Python 解释器和包安装目录。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2. 激活虚拟环境&lt;/strong&gt;: 在使用前，你必须“激活”它。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;Windows:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;.\venv\Scripts\activate&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;macOS / Linux:&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;source venv/bin/activate&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;激活后，你会发现你的命令行提示符前面多了 &lt;code&gt;(venv)&lt;/code&gt; 的字样，表示你正处于这个虚拟环境中。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3. 在虚拟环境中工作&lt;/strong&gt;: 激活后，你使用的 &lt;code&gt;python&lt;/code&gt; 和 &lt;code&gt;pip&lt;/code&gt; 命令都将是该环境内的版本。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;# (venv) D:\path\to\my_project&amp;gt;
pip install requests
pip freeze &amp;gt; requirements.txt&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;现在 &lt;code&gt;requests&lt;/code&gt; 被安装到了 &lt;code&gt;my_project/venv/Lib/site-packages&lt;/code&gt; 目录下，而不是全局。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4. 停用虚拟环境&lt;/strong&gt;: 当你工作完成，想回到全局环境时，只需运行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;deactivate&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;4-3-结合-gitignore&#34;&gt;&lt;a href=&#34;#4-3-结合-gitignore&#34; class=&#34;headerlink&#34; title=&#34;4.3 结合 .gitignore&#34;&gt;&lt;/a&gt;4.3 结合 &lt;code&gt;.gitignore&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;虚拟环境目录 (&lt;code&gt;venv&lt;/code&gt;) 不应该被提交到 Git 等版本控制系统中。它包含了大量文件，并且可以在任何地方通过 &lt;code&gt;requirements.txt&lt;/code&gt; 重建。&lt;/p&gt;
&lt;p&gt;因此，请务必在你的 &lt;code&gt;.gitignore&lt;/code&gt; 文件中添加 &lt;code&gt;venv/&lt;/code&gt; 这一行。&lt;/p&gt;
&lt;h3 id=&#34;总结：专业的开发流程&#34;&gt;&lt;a href=&#34;#总结：专业的开发流程&#34; class=&#34;headerlink&#34; title=&#34;总结：专业的开发流程&#34;&gt;&lt;/a&gt;总结：专业的开发流程&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;项目启动&lt;/strong&gt;：&lt;ul&gt;
&lt;li&gt;创建项目主目录（如 &lt;code&gt;my_project&lt;/code&gt;）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;cd my_project&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;创建虚拟环境：&lt;code&gt;python -m venv venv&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;激活环境：&lt;code&gt;source venv/bin/activate&lt;/code&gt; (或 Windows 对应命令)。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;开发过程&lt;/strong&gt;：&lt;ul&gt;
&lt;li&gt;使用 &lt;code&gt;pip install &amp;lt;package_name&amp;gt;&lt;/code&gt; 安装所需第三方库。&lt;/li&gt;
&lt;li&gt;按照包的结构组织你的代码（创建 &lt;code&gt;my_app&lt;/code&gt;, &lt;code&gt;__init__.py&lt;/code&gt; 等）。&lt;/li&gt;
&lt;li&gt;在包内部优先使用&lt;strong&gt;绝对导入&lt;/strong&gt;，或在必要时使用相对导入。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;依赖管理&lt;/strong&gt;：&lt;ul&gt;
&lt;li&gt;定期更新 &lt;code&gt;requirements.txt&lt;/code&gt; 文件：&lt;code&gt;pip freeze &amp;gt; requirements.txt&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;项目交付/协作&lt;/strong&gt;：&lt;ul&gt;
&lt;li&gt;其他人获取你的代码后，只需重复第一步创建并激活虚拟环境，然后运行 &lt;code&gt;pip install -r requirements.txt&lt;/code&gt; 即可搭建出完全一致的开发环境。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h1 id=&#34;whl文件名后缀&#34;&gt;&lt;a href=&#34;#whl文件名后缀&#34; class=&#34;headerlink&#34; title=&#34;whl文件名后缀&#34;&gt;&lt;/a&gt;whl文件名后缀&lt;/h1&gt;&lt;h2 id=&#34;1-Wheel-文件名的基本格式&#34;&gt;&lt;a href=&#34;#1-Wheel-文件名的基本格式&#34; class=&#34;headerlink&#34; title=&#34;1. Wheel 文件名的基本格式&#34;&gt;&lt;/a&gt;1. Wheel 文件名的基本格式&lt;/h2&gt;&lt;p&gt;Wheel 名称遵循 PEP 427 规范，通用格式为：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-ruby&#34; data-language=&#34;ruby&#34;&gt;&lt;code class=&#34;language-ruby&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;distribution&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;version&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;build tag&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;?&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;python tag&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;abi tag&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;platform tag&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;whl&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;distribution&lt;/strong&gt;：包名&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;version&lt;/strong&gt;：包版本&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;build tag&lt;/strong&gt;（可选）：构建号&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;python tag&lt;/strong&gt;：支持的 Python 解释器及版本&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;abi tag&lt;/strong&gt;：二进制兼容的 ABI（应用二进制接口）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;platform tag&lt;/strong&gt;：目标操作系统和硬件平台&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;例子：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markdown&#34; data-language=&#34;markdown&#34;&gt;&lt;code class=&#34;language-markdown&#34;&gt;mypkg-1.2.3-1-cp39-cp39-manylinux2014_x86_64.whl
       │    │   │    │            └──── platform tag
       │    │   │    └──────────────── abi tag
       │    │   └─────────────────────── python tag
       │    └─────────────────────────── build tag
       └─────────────────────────────── distribution-version&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;2-build-tag&#34;&gt;&lt;a href=&#34;#2-build-tag&#34; class=&#34;headerlink&#34; title=&#34;2. build tag&#34;&gt;&lt;/a&gt;2. build tag&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;格式：一个整数，有时候也会带字母或其他标识&lt;/li&gt;
&lt;li&gt;用途：同一版本的多次编译时区分，比如针对不同源或依赖变动的二进制重构&lt;/li&gt;
&lt;li&gt;示例：&lt;ul&gt;
&lt;li&gt;&lt;code&gt;mypkg-1.0-1-...&lt;/code&gt; 与 &lt;code&gt;mypkg-1.0-2-...&lt;/code&gt; 表示同一版本的第 1 次和第 2 次构建&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;3-python-tag&#34;&gt;&lt;a href=&#34;#3-python-tag&#34; class=&#34;headerlink&#34; title=&#34;3. python tag&#34;&gt;&lt;/a&gt;3. python tag&lt;/h2&gt;&lt;p&gt;指明哪些 Python 解释器及版本可以安装该 Wheel。常见格式及含义：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;tag 示例&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;py3&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;支持所有 Python 3.x&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;py36&lt;/code&gt; 、&lt;code&gt;py37&lt;/code&gt;…&lt;/td&gt;
&lt;td&gt;专用于 Python 3.6、3.7 等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;py2.py3&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;同时支持 Python 2.x 和 3.x&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cp39&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;CPython 3.9&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cp310&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;CPython 3.10&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;pp37&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;PyPy 3.7&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;jy37&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Jython 2.7（标识为 &lt;code&gt;jy27&lt;/code&gt;）等&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;前缀&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;&lt;code&gt;py&lt;/code&gt;：纯 Python 实现&lt;/li&gt;
&lt;li&gt;&lt;code&gt;cp&lt;/code&gt;：CPython（二进制扩展）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;pp&lt;/code&gt;：PyPy&lt;/li&gt;
&lt;li&gt;&lt;code&gt;jy&lt;/code&gt;：Jython&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;4-abi-tag&#34;&gt;&lt;a href=&#34;#4-abi-tag&#34; class=&#34;headerlink&#34; title=&#34;4. abi tag&#34;&gt;&lt;/a&gt;4. abi tag&lt;/h2&gt;&lt;p&gt;ABI（Application Binary Interface）决定了编译的 C 扩展与解释器的二进制兼容性。常见 ABI tag：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;tag 示例&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;none&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;纯 Python 包，不含 C 扩展&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;abi3&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;使用了稳定的“limited API”（PEP 384），跨多个 CPython 版本兼容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cp39&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;针对 CPython 3.9 标准 ABI 编译&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cp39m&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;CPython 3.9 + pymalloc enabled（&lt;code&gt;m&lt;/code&gt;）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cp310d&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;CPython 3.10 Debug build（&lt;code&gt;d&lt;/code&gt;）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;ul&gt;
&lt;li&gt;如果 &lt;code&gt;python tag&lt;/code&gt; 与 &lt;code&gt;abi tag&lt;/code&gt; 一致（如 &lt;code&gt;cp39-cp39&lt;/code&gt;），表示该包针对该版本的标准 ABI 编译&lt;/li&gt;
&lt;li&gt;带后缀的如 &lt;code&gt;m&lt;/code&gt;、&lt;code&gt;d&lt;/code&gt;、&lt;code&gt;u&lt;/code&gt; 等表示特定的编译选项&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;5-platform-tag&#34;&gt;&lt;a href=&#34;#5-platform-tag&#34; class=&#34;headerlink&#34; title=&#34;5. platform tag&#34;&gt;&lt;/a&gt;5. platform tag&lt;/h2&gt;&lt;p&gt;描述该 Wheel 的目标操作系统、系统版本和 CPU 架构。常见平台 tag 及示例：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;platform tag 示例&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;manylinux1_x86_64&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Linux x86_64，符合 Manylinux1 标准&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;manylinux2014_aarch64&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Linux ARM64，符合 Manylinux2014 标准&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;win_amd64&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Windows 64 位&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;win32&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Windows 32 位&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;macosx_10_9_x86_64&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;macOS 10.9+ on x86_64&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;macosx_11_0_arm64&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;macOS 11+ on Apple Silicon (ARM64)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;any&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;平台无关（纯 Python 包）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;manylinux&lt;/strong&gt; 系列：用于在大多数 Linux 发行版上安装二进制扩展&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;macosx&lt;/strong&gt;：通常还会带上最低支持的 macOS 版本号&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;any&lt;/strong&gt;：完全纯 Python，无平台限制&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;6-综合示例解析&#34;&gt;&lt;a href=&#34;#6-综合示例解析&#34; class=&#34;headerlink&#34; title=&#34;6. 综合示例解析&#34;&gt;&lt;/a&gt;6. 综合示例解析&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Wheel 名称&lt;/th&gt;
&lt;th&gt;解释&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;requests-2.28.1-py3-none-any.whl&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;纯 Python 包 &lt;code&gt;requests&lt;/code&gt; v2.28.1，支持所有 Python 3，平台无关&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;numpy-1.24.0-cp39-cp39-manylinux2014_x86_64.whl&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;numpy&lt;/code&gt; v1.24.0，CPython 3.9 标准 ABI，Linux x86_64 二进制&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Pillow-9.3.0-cp310-cp310-win_amd64.whl&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Pillow&lt;/code&gt; v9.3.0，CPython 3.10，Windows 64 位&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;somepkg-0.1.0-2-cp38-abi3-manylinux1_x86_64.whl&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;somepkg&lt;/code&gt; v0.1.0，第 2 次构建，CPython 3.8 编译但使用 abi3，Linux x86_64&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;7-为什么要了解这些后缀&#34;&gt;&lt;a href=&#34;#7-为什么要了解这些后缀&#34; class=&#34;headerlink&#34; title=&#34;7. 为什么要了解这些后缀&#34;&gt;&lt;/a&gt;7. 为什么要了解这些后缀&lt;/h2&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;避免安装失败&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;&lt;code&gt;pip install package.whl&lt;/code&gt; 时，若当前环境的 Python 版本、ABI 或平台与 Wheel 不匹配，安装会被跳过或报错。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;提高下载速度&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;选择预编译好的 &lt;code&gt;.whl&lt;/code&gt;，可免去源码编译时间，尤其是大型 C 扩展库（如 NumPy、SciPy）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;跨平台兼容&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;理解 &lt;code&gt;manylinux&lt;/code&gt;、&lt;code&gt;macosx&lt;/code&gt;、&lt;code&gt;win&lt;/code&gt; 等标签，有助于在不同系统间无痛部署。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;hr&gt;
&lt;h2 id=&#34;8-查找可用的-Wheel&#34;&gt;&lt;a href=&#34;#8-查找可用的-Wheel&#34; class=&#34;headerlink&#34; title=&#34;8. 查找可用的 Wheel&#34;&gt;&lt;/a&gt;8. 查找可用的 Wheel&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip index versions PACKAGE_NAME&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;或&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; PACKAGE_NAME --only-binary&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;:all:&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;第一个命令列出所有可用版本及对应的 Wheel&lt;/li&gt;
&lt;li&gt;第二个命令强制只使用二进制 Wheel 安装&lt;/li&gt;
&lt;/ul&gt;

 &lt;h1 id=&#34;python库报错汇总&#34;&gt;&lt;a href=&#34;#python库报错汇总&#34; class=&#34;headerlink&#34; title=&#34;python库报错汇总&#34;&gt;&lt;/a&gt;python库报错汇总&lt;/h1&gt;&lt;p&gt;形如&lt;code&gt;ModuleNotFoundError: No module named &#39;xxx&#39;&lt;/code&gt;的报错&lt;/p&gt;
&lt;p&gt;首先先试一试&lt;code&gt;pip install xxx&lt;/code&gt;能安装就能解决，没有就看下面，只是我遇到的&lt;/p&gt;
&lt;h2 id=&#34;ModuleNotFoundError-No-module-named-‘cv2’&#34;&gt;&lt;a href=&#34;#ModuleNotFoundError-No-module-named-‘cv2’&#34; class=&#34;headerlink&#34; title=&#34;ModuleNotFoundError: No module named ‘cv2’&#34;&gt;&lt;/a&gt;ModuleNotFoundError: No module named ‘cv2’&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; opencv-contrib-python &lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;ModuleNotFoundError-No-module-named-‘colour-io’-‘colour’-is-not-a-package&#34;&gt;&lt;a href=&#34;#ModuleNotFoundError-No-module-named-‘colour-io’-‘colour’-is-not-a-package&#34; class=&#34;headerlink&#34; title=&#34;ModuleNotFoundError: No module named ‘colour.io’; ‘colour’ is not a package&#34;&gt;&lt;/a&gt;ModuleNotFoundError: No module named ‘colour.io’; ‘colour’ is not a package&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; colour-science&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;No-module-named-‘cpuinfo’&#34;&gt;&lt;a href=&#34;#No-module-named-‘cpuinfo’&#34; class=&#34;headerlink&#34; title=&#34;No module named ‘cpuinfo’&#34;&gt;&lt;/a&gt;No module named ‘cpuinfo’&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; py-cpuinfo&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;ModuleNotFoundError-No-module-named-‘imageio‘&#34;&gt;&lt;a href=&#34;#ModuleNotFoundError-No-module-named-‘imageio‘&#34; class=&#34;headerlink&#34; title=&#34;ModuleNotFoundError: No module named ‘imageio‘&#34;&gt;&lt;/a&gt;ModuleNotFoundError: No module named ‘imageio‘&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; imgaug&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;解决ModuleNotFoundError-No-module-named-‘skimage‘&#34;&gt;&lt;a href=&#34;#解决ModuleNotFoundError-No-module-named-‘skimage‘&#34; class=&#34;headerlink&#34; title=&#34;解决ModuleNotFoundError: No module named ‘skimage‘&#34;&gt;&lt;/a&gt;解决ModuleNotFoundError: No module named ‘skimage‘&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; scikit-image&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;No-module-named-‘open-clip‘&#34;&gt;&lt;a href=&#34;#No-module-named-‘open-clip‘&#34; class=&#34;headerlink&#34; title=&#34;No module named ‘open_clip‘&#34;&gt;&lt;/a&gt;No module named ‘open_clip‘&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; open_clip_torch&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;ERROR-No-matching-distribution-found-for-triton&#34;&gt;&lt;a href=&#34;#ERROR-No-matching-distribution-found-for-triton&#34; class=&#34;headerlink&#34; title=&#34;ERROR: No matching distribution found for triton&#34;&gt;&lt;/a&gt;ERROR: No matching distribution found for triton&lt;/h2&gt;&lt;p&gt;到&lt;a href=&#34;https://hf-mirror.com/madbuda/triton-windows-builds&#34;&gt;madbuda/triton-windows-builds · HF Mirror&lt;/a&gt;下载对应windows构建包&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token builtin class-name&#34;&gt;cd&lt;/span&gt; 下载目录
pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; triton-3.0.0-cp311-cp311-win_amd64.whl  &lt;span class=&#34;token comment&#34;&gt;# 文件名&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;ImportError-cannot-import-name-‘soft-unicode‘-from-‘markupsafe‘&#34;&gt;&lt;a href=&#34;#ImportError-cannot-import-name-‘soft-unicode‘-from-‘markupsafe‘&#34; class=&#34;headerlink&#34; title=&#34;ImportError: cannot import name ‘soft_unicode‘ from ‘markupsafe‘&#34;&gt;&lt;/a&gt;ImportError: cannot import name ‘soft_unicode‘ from ‘markupsafe‘&lt;/h2&gt;&lt;p&gt;执行命令重新安装&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token assign-left variable&#34;&gt;markupsafe&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2.0&lt;/span&gt;.1&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;No-module-named-‘sklearn’&#34;&gt;&lt;a href=&#34;#No-module-named-‘sklearn’&#34; class=&#34;headerlink&#34; title=&#34;No module named ‘sklearn’&#34;&gt;&lt;/a&gt;No module named ‘sklearn’&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; scikit-learn&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;



&lt;h2 id=&#34;其他&#34;&gt;&lt;a href=&#34;#其他&#34; class=&#34;headerlink&#34; title=&#34;其他&#34;&gt;&lt;/a&gt;其他&lt;/h2&gt;&lt;p&gt;ERROR: Could not install packages due to an OSError: [WinError 5] 拒绝访问。： ‘E:\conda\envs\deepl\Lib\site-packages\cv2\cv2.pyd’ Consider using the &lt;code&gt;--user&lt;/code&gt; option or check the permissions.&lt;/p&gt;
&lt;p&gt;如他说添加&lt;code&gt;--user&lt;/code&gt;参数&lt;/p&gt;

 &lt;h1 id=&#34;python库merklelib&#34;&gt;&lt;a href=&#34;#python库merklelib&#34; class=&#34;headerlink&#34; title=&#34;python库merklelib&#34;&gt;&lt;/a&gt;python库merklelib&lt;/h1&gt;&lt;h2 id=&#34;报错AttributeError-module-‘collections’-has-no-attribute-‘Iterable’&#34;&gt;&lt;a href=&#34;#报错AttributeError-module-‘collections’-has-no-attribute-‘Iterable’&#34; class=&#34;headerlink&#34; title=&#34;报错AttributeError: module ‘collections’ has no attribute ‘Iterable’&#34;&gt;&lt;/a&gt;报错AttributeError: module ‘collections’ has no attribute ‘Iterable’&lt;/h2&gt;&lt;p&gt;该错误发生在 Python 3.10 或更高版本中，因为 &lt;code&gt;collections.Iterable&lt;/code&gt; 在 Python 3.10 中已被移至 &lt;code&gt;collections.abc.Iterable&lt;/code&gt;。这是 Python 的一个兼容性问题。&lt;/p&gt;
&lt;p&gt;要解决此问题，请将代码中的 &lt;code&gt;collections.Iterable&lt;/code&gt; 替换为 &lt;code&gt;collections.abc.Iterable&lt;/code&gt;：&lt;/p&gt;
&lt;h3 id=&#34;修改代码&#34;&gt;&lt;a href=&#34;#修改代码&#34; class=&#34;headerlink&#34; title=&#34;修改代码&#34;&gt;&lt;/a&gt;修改代码&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; collections&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;abc

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;not&lt;/span&gt; &lt;span class=&#34;token builtin&#34;&gt;isinstance&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;data&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; collections&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;abc&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Iterable&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token comment&#34;&gt;# Your logic here&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;如果你正在使用一个依赖于旧版 &lt;code&gt;collections.Iterable&lt;/code&gt; 的库（如 &lt;code&gt;merklelib&lt;/code&gt;），可以通过以下方式解决：&lt;/p&gt;
&lt;h3 id=&#34;解决方法-1：升级相关库&#34;&gt;&lt;a href=&#34;#解决方法-1：升级相关库&#34; class=&#34;headerlink&#34; title=&#34;解决方法 1：升级相关库&#34;&gt;&lt;/a&gt;解决方法 1：升级相关库&lt;/h3&gt;&lt;p&gt;检查是否有更新的版本来支持 Python 3.10+。你可以尝试更新库：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;--upgrade&lt;/span&gt; merklelib&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;解决方法-2：兼容性修复&#34;&gt;&lt;a href=&#34;#解决方法-2：兼容性修复&#34; class=&#34;headerlink&#34; title=&#34;解决方法 2：兼容性修复&#34;&gt;&lt;/a&gt;解决方法 2：兼容性修复&lt;/h3&gt;&lt;p&gt;如果库尚未更新，你可以手动修复代码：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;打开出错的代码文件（通常在库的安装目录中）。&lt;/li&gt;
&lt;li&gt;找到 &lt;code&gt;collections.Iterable&lt;/code&gt; 并替换为 &lt;code&gt;collections.abc.Iterable&lt;/code&gt;。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;或者，临时修复可以通过 Monkey Patch：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; collections&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;abc
collections&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Iterable &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; collections&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;abc&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Iterable&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;解决方法-3：降级-Python-版本&#34;&gt;&lt;a href=&#34;#解决方法-3：降级-Python-版本&#34; class=&#34;headerlink&#34; title=&#34;解决方法 3：降级 Python 版本&#34;&gt;&lt;/a&gt;解决方法 3：降级 Python 版本&lt;/h3&gt;&lt;p&gt;如果无法更新库或代码，可以暂时降级到 Python 3.9：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyenv &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;3.9&lt;/span&gt;.12
pyenv global &lt;span class=&#34;token number&#34;&gt;3.9&lt;/span&gt;.12&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;推荐优先升级库或修复代码以适应 Python 的新版本&lt;/p&gt;

 &lt;h1 id=&#34;flask教程&#34;&gt;&lt;a href=&#34;#flask教程&#34; class=&#34;headerlink&#34; title=&#34;flask教程&#34;&gt;&lt;/a&gt;flask教程&lt;/h1&gt;&lt;h2 id=&#34;项目结构&#34;&gt;&lt;a href=&#34;#项目结构&#34; class=&#34;headerlink&#34; title=&#34;项目结构&#34;&gt;&lt;/a&gt;项目结构&lt;/h2&gt;&lt;h3 id=&#34;中型&#34;&gt;&lt;a href=&#34;#中型&#34; class=&#34;headerlink&#34; title=&#34;中型&#34;&gt;&lt;/a&gt;中型&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-dtd&#34; data-language=&#34;dtd&#34;&gt;&lt;code class=&#34;language-dtd&#34;&gt;my_flask_project/
├── app/                     # 核心应用文件夹
│   ├── __init__.py          # 应用初始化
│   ├── routes.py            # 路由定义
│   ├── models.py            # 数据模型（如需要）
│   ├── templates/           # HTML 模板
│   │   └── index.html
│   └── static/              # 静态文件
│       ├── css/
│       │   └── style.css
│       └── js/
│           └── script.js
├── config.py                # 配置文件
├── run.py                   # 启动文件
└── requirements.txt         # 依赖文件&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;app-init-py&#34;&gt;&lt;a href=&#34;#app-init-py&#34; class=&#34;headerlink&#34; title=&#34;app/__init__.py&#34;&gt;&lt;/a&gt;&lt;code&gt;app/__init__.py&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;在 &lt;code&gt;__init__.py&lt;/code&gt; 中创建并初始化 Flask 应用，加载配置，并从 &lt;code&gt;routes.py&lt;/code&gt; 注册路由。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;create_app&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;config&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;from_object&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;config.Config&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 加载配置&lt;/span&gt;

    &lt;span class=&#34;token keyword&#34;&gt;with&lt;/span&gt; app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;app_context&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token comment&#34;&gt;# 导入并注册路由&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; routes
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; app&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;code&gt;create_app&lt;/code&gt; 函数用于创建和配置应用实例。&lt;code&gt;app.app_context()&lt;/code&gt; 确保在应用上下文中导入路由。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;app-routes-py&#34;&gt;&lt;a href=&#34;#app-routes-py&#34; class=&#34;headerlink&#34; title=&#34;app/routes.py&#34;&gt;&lt;/a&gt;&lt;code&gt;app/routes.py&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;定义项目的路由，所有路由相关的逻辑放在这个文件中。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; current_app &lt;span class=&#34;token keyword&#34;&gt;as&lt;/span&gt; app

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;index.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;code&gt;app.route(&#39;/&#39;)&lt;/code&gt; 是根路径的路由，返回 &lt;code&gt;index.html&lt;/code&gt; 模板页面。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;app-models-py-（可选）&#34;&gt;&lt;a href=&#34;#app-models-py-（可选）&#34; class=&#34;headerlink&#34; title=&#34;app/models.py （可选）&#34;&gt;&lt;/a&gt;&lt;code&gt;app/models.py&lt;/code&gt; （可选）&lt;/h4&gt;&lt;p&gt;如果项目需要数据库模型，可以在此文件中定义。例如：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask_sqlalchemy &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; SQLAlchemy

db &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; SQLAlchemy&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;User&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;db&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Model&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token builtin&#34;&gt;id&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; db&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Column&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;db&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Integer&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; primary_key&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;True&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    username &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; db&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;Column&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;db&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;String&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;150&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; nullable&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;False&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; unique&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;True&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;config-py&#34;&gt;&lt;a href=&#34;#config-py&#34; class=&#34;headerlink&#34; title=&#34;config.py&#34;&gt;&lt;/a&gt;&lt;code&gt;config.py&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;配置文件，用于管理全局配置（例如密钥、数据库 URI 等）。将敏感信息存储在环境变量中更安全。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; os

&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;Config&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    SECRET_KEY &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;environ&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;get&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;SECRET_KEY&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;or&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;your_secret_key&#39;&lt;/span&gt;
    SQLALCHEMY_DATABASE_URI &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;sqlite:///site.db&#39;&lt;/span&gt;
    SQLALCHEMY_TRACK_MODIFICATIONS &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token boolean&#34;&gt;False&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;app-templates-index-html&#34;&gt;&lt;a href=&#34;#app-templates-index-html&#34; class=&#34;headerlink&#34; title=&#34;app/templates/index.html&#34;&gt;&lt;/a&gt;&lt;code&gt;app/templates/index.html&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;HTML 模板文件示例。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token doctype&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;!&lt;/span&gt;&lt;span class=&#34;token doctype-tag&#34;&gt;DOCTYPE&lt;/span&gt; &lt;span class=&#34;token name&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;html&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;lang&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;en&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;meta&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;charset&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;UTF-8&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;My Flask App&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;link&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;rel&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;stylesheet&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;href&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;{{ url_for(&#39;static&#39;, filename=&#39;css/style.css&#39;) }}&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Welcome to My Flask App&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Hello, Flask with modular structure!&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;script&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;src&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;{{ url_for(&#39;static&#39;, filename=&#39;js/script.js&#39;) }}&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token script&#34;&gt;&lt;/span&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;script&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;app-static-css-style-css&#34;&gt;&lt;a href=&#34;#app-static-css-style-css&#34; class=&#34;headerlink&#34; title=&#34;app/static/css/style.css&#34;&gt;&lt;/a&gt;&lt;code&gt;app/static/css/style.css&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;简单的 CSS 文件，用于为页面增加样式。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-css&#34; data-language=&#34;css&#34;&gt;&lt;code class=&#34;language-css&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;/* static/css/style.css */&lt;/span&gt;
&lt;span class=&#34;token selector&#34;&gt;body&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;font-family&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; Arial&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sans-serif&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;background-color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; #f0f0f0&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;app-static-js-script-js&#34;&gt;&lt;a href=&#34;#app-static-js-script-js&#34; class=&#34;headerlink&#34; title=&#34;app/static/js/script.js&#34;&gt;&lt;/a&gt;&lt;code&gt;app/static/js/script.js&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;简单的 JavaScript 文件。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-javascript&#34; data-language=&#34;javascript&#34;&gt;&lt;code class=&#34;language-javascript&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;// static/js/script.js&lt;/span&gt;
console&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;log&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Welcome to My Flask App with modular structure!&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;run-py&#34;&gt;&lt;a href=&#34;#run-py&#34; class=&#34;headerlink&#34; title=&#34;run.py&#34;&gt;&lt;/a&gt;&lt;code&gt;run.py&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;项目的启动文件，通过调用 &lt;code&gt;create_app&lt;/code&gt; 函数启动应用。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; app &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; create_app

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; create_app&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; __name__ &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;__main__&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;run&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;debug&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;True&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;code&gt;run.py&lt;/code&gt; 是整个项目的入口文件，使用 &lt;code&gt;app.run(debug=True)&lt;/code&gt; 启动应用程序。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;requirements-txt&#34;&gt;&lt;a href=&#34;#requirements-txt&#34; class=&#34;headerlink&#34; title=&#34;requirements.txt&#34;&gt;&lt;/a&gt;&lt;code&gt;requirements.txt&lt;/code&gt;&lt;/h4&gt;&lt;p&gt;包含项目依赖。&lt;/p&gt;
&lt;h3 id=&#34;大型&#34;&gt;&lt;a href=&#34;#大型&#34; class=&#34;headerlink&#34; title=&#34;大型&#34;&gt;&lt;/a&gt;大型&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-dtd&#34; data-language=&#34;dtd&#34;&gt;&lt;code class=&#34;language-dtd&#34;&gt;my_flask_project/
├── app/
│   ├── __init__.py           # 初始化应用程序和配置
│   ├── routes.py             # 路由定义
│   ├── models.py             # 数据库模型定义
│   ├── templates/            # HTML 模板文件
│   │   └── base.html
│   ├── static/               # 静态文件（CSS、JS、图片等）
│   │   ├── css/
│   │   │   └── style.css
│   │   ├── js/
│   │   └── images/
│   └── blueprints/           # 各个功能模块的蓝图
│       ├── __init__.py
│       ├── user/             # 用户模块
│       │   ├── __init__.py
│       │   ├── routes.py
│       │   └── templates/
│       └── admin/            # 管理员模块
│           ├── __init__.py
│           ├── routes.py
│           └── templates/
├── migrations/               # 数据库迁移文件（使用 Flask-Migrate）
├── tests/                    # 测试代码
│   ├── __init__.py
│   └── test_app.py
├── config.py                 # 配置文件
├── manage.py                 # 启动、管理和迁移命令
└── requirements.txt          # 依赖包&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;p&gt;**&lt;code&gt;app/&lt;/code&gt;**：主要应用程序文件夹，包含所有核心代码。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;**&lt;code&gt;__init__.py&lt;/code&gt;**：初始化 Flask 应用、加载配置和注册蓝图。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;routes.py&lt;/code&gt;**：定义全局路由。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;models.py&lt;/code&gt;**：定义数据库模型。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;templates/&lt;/code&gt;**：存储 HTML 模板。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;static/&lt;/code&gt;**：存储静态文件，如 CSS、JavaScript 和图片。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;blueprints/&lt;/code&gt;**：存储不同功能模块的蓝图，每个模块可以有自己的 &lt;code&gt;routes.py&lt;/code&gt; 和 &lt;code&gt;templates/&lt;/code&gt; 文件夹。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;**&lt;code&gt;migrations/&lt;/code&gt;**：数据库迁移文件（如使用 Flask-Migrate 时生成）。&lt;/p&gt;
&lt;p&gt;**&lt;code&gt;tests/&lt;/code&gt;**：测试文件夹，用于单元测试或集成测试。&lt;/p&gt;
&lt;p&gt;**&lt;code&gt;config.py&lt;/code&gt;**：存储配置文件，如数据库连接和应用的全局设置。&lt;/p&gt;
&lt;p&gt;**&lt;code&gt;manage.py&lt;/code&gt;**：用于管理项目的文件，可添加自定义命令，如启动服务器、初始化数据库等。&lt;/p&gt;
&lt;p&gt;**&lt;code&gt;requirements.txt&lt;/code&gt;**：记录项目的所有依赖包。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;路由&#34;&gt;&lt;a href=&#34;#路由&#34; class=&#34;headerlink&#34; title=&#34;路由&#34;&gt;&lt;/a&gt;路由&lt;/h2&gt;&lt;h3 id=&#34;1-基本路由&#34;&gt;&lt;a href=&#34;#1-基本路由&#34; class=&#34;headerlink&#34; title=&#34;1. 基本路由&#34;&gt;&lt;/a&gt;1. 基本路由&lt;/h3&gt;&lt;p&gt;最简单的路由是将一个 URL 映射到一个视图函数。可以使用 &lt;code&gt;@app.route()&lt;/code&gt; 装饰器来定义路由。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Welcome to the homepage!&#34;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/about&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;about&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;This is the about page.&#34;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;@app.route(&#39;/&#39;)&lt;/code&gt;：当用户访问根路径（如 &lt;code&gt;http://localhost:5000/&lt;/code&gt;）时，执行 &lt;code&gt;home&lt;/code&gt; 函数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;@app.route(&#39;/about&#39;)&lt;/code&gt;：访问 &lt;code&gt;/about&lt;/code&gt; 时，执行 &lt;code&gt;about&lt;/code&gt; 函数。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;2-动态路由&#34;&gt;&lt;a href=&#34;#2-动态路由&#34; class=&#34;headerlink&#34; title=&#34;2. 动态路由&#34;&gt;&lt;/a&gt;2. 动态路由&lt;/h3&gt;&lt;p&gt;可以在路由中添加动态部分，用来接收 URL 中的参数。动态部分用尖括号 &lt;code&gt;&amp;lt;...&amp;gt;&lt;/code&gt; 表示，Flask 会自动将 URL 中的值传递给视图函数。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/user/&amp;lt;username&amp;gt;&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;show_user&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;Hello, &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;!&#34;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;访问 &lt;code&gt;/user/john&lt;/code&gt; 时，会输出 &lt;code&gt;Hello, john!&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;lt;username&amp;gt;&lt;/code&gt; 是一个动态参数，视图函数 &lt;code&gt;show_user&lt;/code&gt; 将接收 &lt;code&gt;username&lt;/code&gt; 的值。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;指定数据类型&#34;&gt;&lt;a href=&#34;#指定数据类型&#34; class=&#34;headerlink&#34; title=&#34;指定数据类型&#34;&gt;&lt;/a&gt;指定数据类型&lt;/h4&gt;&lt;p&gt;默认情况下，Flask 会将 URL 参数作为字符串处理。如果需要其他类型的数据，可以在尖括号内指定：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/post/&amp;lt;int:post_id&amp;gt;&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;show_post&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;post_id&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;Post ID is &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;post_id&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;&amp;lt;int:post_id&amp;gt;&lt;/code&gt; 指定了 &lt;code&gt;post_id&lt;/code&gt; 必须是整数，访问 &lt;code&gt;/post/5&lt;/code&gt; 会返回 &lt;code&gt;Post ID is 5&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;常用的数据类型有：&lt;ul&gt;
&lt;li&gt;&lt;code&gt;&amp;lt;int:variable&amp;gt;&lt;/code&gt;：整数&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;lt;float:variable&amp;gt;&lt;/code&gt;：浮点数&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;lt;path:variable&amp;gt;&lt;/code&gt;：字符串（允许包含 &lt;code&gt;/&lt;/code&gt;）&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;3-多种请求方法&#34;&gt;&lt;a href=&#34;#3-多种请求方法&#34; class=&#34;headerlink&#34; title=&#34;3. 多种请求方法&#34;&gt;&lt;/a&gt;3. 多种请求方法&lt;/h3&gt;&lt;p&gt;默认情况下，Flask 路由只响应 &lt;code&gt;GET&lt;/code&gt; 请求。如果需要处理其他 HTTP 方法（如 &lt;code&gt;POST&lt;/code&gt;、&lt;code&gt;PUT&lt;/code&gt;、&lt;code&gt;DELETE&lt;/code&gt; 等），可以通过 &lt;code&gt;methods&lt;/code&gt; 参数指定。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/submit&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; methods&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;GET&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;submit&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;method &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Form submitted!&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Please submit the form.&#34;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;methods=[&#39;GET&#39;, &#39;POST&#39;]&lt;/code&gt;：允许 &lt;code&gt;submit&lt;/code&gt; 路由响应 &lt;code&gt;GET&lt;/code&gt; 和 &lt;code&gt;POST&lt;/code&gt; 请求。&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;request.method&lt;/code&gt; 判断请求类型并做不同的处理。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;4-路由别名（URL-别名）&#34;&gt;&lt;a href=&#34;#4-路由别名（URL-别名）&#34; class=&#34;headerlink&#34; title=&#34;4. 路由别名（URL 别名）&#34;&gt;&lt;/a&gt;4. 路由别名（URL 别名）&lt;/h3&gt;&lt;p&gt;可以使用 &lt;code&gt;url_for&lt;/code&gt; 函数生成路由的 URL，避免硬编码 URL。在视图函数上使用 &lt;code&gt;endpoint&lt;/code&gt; 参数，可以给路由一个别名，用于简化 &lt;code&gt;url_for&lt;/code&gt; 函数调用。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; url_for

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/profile/&amp;lt;username&amp;gt;&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; endpoint&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;user_profile&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;profile&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;User: &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 使用 url_for 动态生成 URL&lt;/span&gt;
&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/redirect_to_profile&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;redirect_to_profile&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; redirect&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;url_for&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;user_profile&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; username&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;john&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;访问 &lt;code&gt;/redirect_to_profile&lt;/code&gt; 会重定向到 &lt;code&gt;/profile/john&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;5-重定向与错误处理&#34;&gt;&lt;a href=&#34;#5-重定向与错误处理&#34; class=&#34;headerlink&#34; title=&#34;5. 重定向与错误处理&#34;&gt;&lt;/a&gt;5. 重定向与错误处理&lt;/h3&gt;&lt;p&gt;可以通过 &lt;code&gt;redirect&lt;/code&gt; 实现重定向，或用 &lt;code&gt;abort&lt;/code&gt; 函数处理错误。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; redirect&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; abort

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/old-url&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;old_url&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token comment&#34;&gt;# 重定向到新的 URL&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; redirect&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;url_for&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;new_url&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/new-url&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;new_url&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;This is the new URL.&#34;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/secret&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;secret&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    abort&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;403&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 返回 403 错误&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;redirect(url_for(&#39;new_url&#39;))&lt;/code&gt;：将用户重定向到 &lt;code&gt;new_url&lt;/code&gt; 视图。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;abort(403)&lt;/code&gt;：返回 403 错误页面。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;6-带查询参数的路由&#34;&gt;&lt;a href=&#34;#6-带查询参数的路由&#34; class=&#34;headerlink&#34; title=&#34;6. 带查询参数的路由&#34;&gt;&lt;/a&gt;6. 带查询参数的路由&lt;/h3&gt;&lt;p&gt;查询参数一般附加在 URL 的末尾，例如 &lt;code&gt;http://localhost:5000/search?query=flask&lt;/code&gt;。可以通过 &lt;code&gt;request.args&lt;/code&gt; 获取这些参数。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; request

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/search&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;search&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    query &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;args&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;get&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;query&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;Search results for: &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;query&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;request.args.get(&#39;query&#39;)&lt;/code&gt;：获取查询参数 &lt;code&gt;query&lt;/code&gt; 的值。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;7-路由分组（蓝图）&#34;&gt;&lt;a href=&#34;#7-路由分组（蓝图）&#34; class=&#34;headerlink&#34; title=&#34;7. 路由分组（蓝图）&#34;&gt;&lt;/a&gt;7. 路由分组（蓝图）&lt;/h3&gt;&lt;p&gt;如果应用较大，可以将路由划分为不同的模块（称为“蓝图”），以提高代码组织性。以下是一个简单的蓝图示例。&lt;/p&gt;
&lt;h4 id=&#34;创建蓝图文件-app-user-py：&#34;&gt;&lt;a href=&#34;#创建蓝图文件-app-user-py：&#34; class=&#34;headerlink&#34; title=&#34;创建蓝图文件 app/user.py：&#34;&gt;&lt;/a&gt;创建蓝图文件 &lt;code&gt;app/user.py&lt;/code&gt;：&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Blueprint

user_bp &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Blueprint&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;user&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; __name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@user_bp&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&amp;lt;username&amp;gt;&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;profile&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;User Profile for &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;注册蓝图到应用中-app-init-py：&#34;&gt;&lt;a href=&#34;#注册蓝图到应用中-app-init-py：&#34; class=&#34;headerlink&#34; title=&#34;注册蓝图到应用中 app/__init__.py：&#34;&gt;&lt;/a&gt;注册蓝图到应用中 &lt;code&gt;app/__init__.py&lt;/code&gt;：&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;user &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; user_bp

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;create_app&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;register_blueprint&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;user_bp&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; url_prefix&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/user&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 注册蓝图&lt;/span&gt;

    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; app&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;url_prefix=&#39;/user&#39;&lt;/code&gt;：访问 &lt;code&gt;/user/&amp;lt;username&amp;gt;&lt;/code&gt; 时，会调用 &lt;code&gt;user_bp&lt;/code&gt; 蓝图中的 &lt;code&gt;profile&lt;/code&gt; 路由。&lt;/li&gt;
&lt;li&gt;蓝图让大型应用代码更清晰。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;8-格式化&#34;&gt;&lt;a href=&#34;#8-格式化&#34; class=&#34;headerlink&#34; title=&#34;8. 格式化&#34;&gt;&lt;/a&gt;8. 格式化&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; jsonify

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/json&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;json_data&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;name&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Flask&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;version&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;2.0&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; jsonify&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;data&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;9-视图函数的装饰器&#34;&gt;&lt;a href=&#34;#9-视图函数的装饰器&#34; class=&#34;headerlink&#34; title=&#34;9.视图函数的装饰器&#34;&gt;&lt;/a&gt;9.视图函数的装饰器&lt;/h3&gt;&lt;p&gt;除了 @app.route，Flask 还支持其他装饰器，用于实现更复杂的功能。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;**&lt;code&gt;@app.before_request&lt;/code&gt;**：在每个请求处理之前运行的函数。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;@app.after_request&lt;/code&gt;**：在每个请求处理之后运行的函数。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;@app.teardown_request&lt;/code&gt;**：在请求结束后运行的函数，用于清理工作。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;示例装饰器使用：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;before_request&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;before_request&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
  &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Before request&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;after_request&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;after_request&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;response&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
  &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;After request&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
  &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; response

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;teardown_request&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;teardown_request&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;exception&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
  &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Teardown request&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;完整示例&#34;&gt;&lt;a href=&#34;#完整示例&#34; class=&#34;headerlink&#34; title=&#34;完整示例&#34;&gt;&lt;/a&gt;完整示例&lt;/h3&gt;&lt;p&gt;以下是一个包含多种路由定义方式的完整示例：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; redirect&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; url_for&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; abort&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; jsonify

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Welcome to the homepage!&#34;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/user/&amp;lt;username&amp;gt;&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;show_user&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;Hello, &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;!&#34;&lt;/span&gt;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/post/&amp;lt;int:post_id&amp;gt;&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;show_post&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;post_id&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;Post ID is &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;post_id&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/submit&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; methods&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;GET&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;submit&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;method &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Form submitted!&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Please submit the form.&#34;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/search&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;search&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    query &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;args&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;get&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;query&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;Search results for: &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;query&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/json&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;json_data&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;name&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Flask&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;version&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;2.0&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; jsonify&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;data&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/old-url&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;old_url&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; redirect&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;url_for&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;home&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/secret&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;secret&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    abort&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;403&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;Flask-模板渲染&#34;&gt;&lt;a href=&#34;#Flask-模板渲染&#34; class=&#34;headerlink&#34; title=&#34;Flask 模板渲染&#34;&gt;&lt;/a&gt;Flask 模板渲染&lt;/h2&gt;&lt;p&gt;在 Flask 中，模板渲染是生成动态 HTML 页面的一种方法。Flask 使用 Jinja2 模板引擎来帮助你在 HTML 中插入变量、控制结构（如条件判断、循环）等内容，以便动态生成页面。&lt;/p&gt;
&lt;h3 id=&#34;1-设置模板文件夹&#34;&gt;&lt;a href=&#34;#1-设置模板文件夹&#34; class=&#34;headerlink&#34; title=&#34;1. 设置模板文件夹&#34;&gt;&lt;/a&gt;1. 设置模板文件夹&lt;/h3&gt;&lt;p&gt;在 Flask 项目中，默认的模板文件夹是 &lt;code&gt;templates&lt;/code&gt;，建议将所有 HTML 模板文件放在这个文件夹中。Flask 会自动寻找并渲染该目录中的模板文件。&lt;/p&gt;
&lt;h3 id=&#34;2-创建基本-HTML-模板&#34;&gt;&lt;a href=&#34;#2-创建基本-HTML-模板&#34; class=&#34;headerlink&#34; title=&#34;2. 创建基本 HTML 模板&#34;&gt;&lt;/a&gt;2. 创建基本 HTML 模板&lt;/h3&gt;&lt;p&gt;假设我们在 &lt;code&gt;templates/index.html&lt;/code&gt; 中创建了一个基本的 HTML 模板文件：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;&amp;lt;!-- templates/index.html --&amp;gt;&lt;/span&gt;
&lt;span class=&#34;token doctype&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;!&lt;/span&gt;&lt;span class=&#34;token doctype-tag&#34;&gt;DOCTYPE&lt;/span&gt; &lt;span class=&#34;token name&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;html&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;lang&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;en&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;meta&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;charset&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;UTF-8&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{{ title }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{{ heading }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{{ content }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;在这个模板中：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;{{ title }}&lt;/code&gt;、&lt;code&gt;{{ heading }}&lt;/code&gt; 和 &lt;code&gt;{{ content }}&lt;/code&gt; 是变量占位符，在渲染模板时会被 Flask 替换成实际的值。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;3-渲染模板&#34;&gt;&lt;a href=&#34;#3-渲染模板&#34; class=&#34;headerlink&#34; title=&#34;3. 渲染模板&#34;&gt;&lt;/a&gt;3. 渲染模板&lt;/h3&gt;&lt;p&gt;在 Flask 中，可以使用 &lt;code&gt;render_template&lt;/code&gt; 函数来渲染 HTML 模板，并将变量传递给模板。下面是一个简单的视图函数，渲染上面的 &lt;code&gt;index.html&lt;/code&gt; 模板。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; render_template

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;index.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; title&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Home Page&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; heading&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Welcome to My Website&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; content&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;This is the home page content.&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;render_template(&#39;index.html&#39;, ...)&lt;/code&gt;：&lt;code&gt;render_template&lt;/code&gt; 函数会在 &lt;code&gt;templates&lt;/code&gt; 文件夹中找到 &lt;code&gt;index.html&lt;/code&gt; 文件，并将指定变量传入模板。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;title=&#34;Home Page&#34;&lt;/code&gt;：将 &lt;code&gt;title&lt;/code&gt; 变量的值传入模板，模板中的 &lt;code&gt;{{ title }}&lt;/code&gt; 将被替换为 &lt;code&gt;Home Page&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;4-模板变量和控制结构&#34;&gt;&lt;a href=&#34;#4-模板变量和控制结构&#34; class=&#34;headerlink&#34; title=&#34;4. 模板变量和控制结构&#34;&gt;&lt;/a&gt;4. 模板变量和控制结构&lt;/h3&gt;&lt;p&gt;Jinja2 模板支持在 HTML 中使用变量、控制结构（条件、循环）等操作。&lt;/p&gt;
&lt;h4 id=&#34;变量&#34;&gt;&lt;a href=&#34;#变量&#34; class=&#34;headerlink&#34; title=&#34;变量&#34;&gt;&lt;/a&gt;变量&lt;/h4&gt;&lt;p&gt;使用双大括号 &lt;code&gt;{{ ... }}&lt;/code&gt; 在模板中插入变量。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Hello, {{ name }}!&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;条件语句&#34;&gt;&lt;a href=&#34;#条件语句&#34; class=&#34;headerlink&#34; title=&#34;条件语句&#34;&gt;&lt;/a&gt;条件语句&lt;/h4&gt;&lt;p&gt;使用 &lt;code&gt;{% if ... %}` 和 `{% endif %}&lt;/code&gt; 添加条件逻辑：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;{% if user_is_logged_in %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Welcome back, {{ username }}!&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
{% else %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Please log in to access your account.&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
{% endif %}&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;循环&#34;&gt;&lt;a href=&#34;#循环&#34; class=&#34;headerlink&#34; title=&#34;循环&#34;&gt;&lt;/a&gt;循环&lt;/h4&gt;&lt;p&gt;使用 &lt;code&gt;{% for ... in ... %}` 和 `{% endfor %}&lt;/code&gt; 添加循环：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;ul&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    {% for item in items %}
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;li&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{{ item }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;li&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    {% endfor %}
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;ul&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;5-继承与块&#34;&gt;&lt;a href=&#34;#5-继承与块&#34; class=&#34;headerlink&#34; title=&#34;5. 继承与块&#34;&gt;&lt;/a&gt;5. 继承与块&lt;/h3&gt;&lt;p&gt;Jinja2 支持模板继承，可以创建一个基础模板供其他模板继承。可以将公共结构（如导航栏、页脚等）放在基础模板中，然后在子模板中覆盖特定部分。&lt;/p&gt;
&lt;h4 id=&#34;基础模板-templates-base-html&#34;&gt;&lt;a href=&#34;#基础模板-templates-base-html&#34; class=&#34;headerlink&#34; title=&#34;基础模板 templates/base.html&#34;&gt;&lt;/a&gt;基础模板 &lt;code&gt;templates/base.html&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token doctype&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;!&lt;/span&gt;&lt;span class=&#34;token doctype-tag&#34;&gt;DOCTYPE&lt;/span&gt; &lt;span class=&#34;token name&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;html&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;lang&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;en&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;meta&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;charset&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;UTF-8&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{% block title %}My Website{% endblock %}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;header&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;My Website&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;header&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;main&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% block content %}{% endblock %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;main&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;footer&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;© 2024 My Website&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;footer&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;{% block title %}` 和 `{% block content %}` 是块占位符，子模板可以覆盖这些内容。

#### 子模板 `templates/index.html`

&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;{% extends &#34;base.html&#34; %}

{% block title %}Home Page{% endblock %}

{% block content %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Welcome to the Home Page&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;This is some content specific to the home page.&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
{% endblock %}&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

- `{% extends &#34;base.html&#34; %}` 表示继承 `base.html` 模板。
- `{% block title %}Home Page{% endblock %}&lt;/code&gt;：覆盖了基础模板中的 &lt;code&gt;title&lt;/code&gt; 块。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;{% block content %}...{% endblock %}&lt;/code&gt;：覆盖了基础模板中的 &lt;code&gt;content&lt;/code&gt; 块。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;6-使用静态文件&#34;&gt;&lt;a href=&#34;#6-使用静态文件&#34; class=&#34;headerlink&#34; title=&#34;6. 使用静态文件&#34;&gt;&lt;/a&gt;6. 使用静态文件&lt;/h3&gt;&lt;p&gt;Flask 默认将静态文件放在 &lt;code&gt;static&lt;/code&gt; 文件夹中，例如 CSS、JavaScript 文件等。在模板中，可以通过 &lt;code&gt;url_for(&#39;static&#39;, filename=&#39;...&#39;)&lt;/code&gt; 生成静态文件的 URL。&lt;/p&gt;
&lt;p&gt;假设有一个 CSS 文件 &lt;code&gt;static/style.css&lt;/code&gt;，可以在模板中引入：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;&amp;lt;!-- 在 base.html 中引入 CSS 文件 --&amp;gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;link&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;rel&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;stylesheet&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;href&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;{{ url_for(&#39;static&#39;, filename=&#39;style.css&#39;) }}&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;7-完整示例&#34;&gt;&lt;a href=&#34;#7-完整示例&#34; class=&#34;headerlink&#34; title=&#34;7. 完整示例&#34;&gt;&lt;/a&gt;7. 完整示例&lt;/h3&gt;&lt;p&gt;以下是包含基础模板、变量、循环、条件的完整 Flask 应用示例。&lt;/p&gt;
&lt;h4 id=&#34;项目结构-1&#34;&gt;&lt;a href=&#34;#项目结构-1&#34; class=&#34;headerlink&#34; title=&#34;项目结构&#34;&gt;&lt;/a&gt;项目结构&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-csharp&#34; data-language=&#34;csharp&#34;&gt;&lt;code class=&#34;language-csharp&#34;&gt;my_flask_app&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;
├── app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;py
├── templates&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;
│   ├── &lt;span class=&#34;token keyword&#34;&gt;base&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;html
│   ├── index&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;html
└── &lt;span class=&#34;token keyword&#34;&gt;static&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;
    └── style&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;css&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;app-py&#34;&gt;&lt;a href=&#34;#app-py&#34; class=&#34;headerlink&#34; title=&#34;app.py&#34;&gt;&lt;/a&gt;&lt;code&gt;app.py&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; render_template

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    items &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Item 1&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Item 2&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Item 3&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;
    user_is_logged_in &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token boolean&#34;&gt;True&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;index.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; title&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Home Page&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; items&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;items&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; user_is_logged_in&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;user_is_logged_in&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; username&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;John Doe&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;templates-base-html&#34;&gt;&lt;a href=&#34;#templates-base-html&#34; class=&#34;headerlink&#34; title=&#34;templates/base.html&#34;&gt;&lt;/a&gt;&lt;code&gt;templates/base.html&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token doctype&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;!&lt;/span&gt;&lt;span class=&#34;token doctype-tag&#34;&gt;DOCTYPE&lt;/span&gt; &lt;span class=&#34;token name&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;html&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;lang&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;en&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;meta&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;charset&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;UTF-8&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{% block title %}My Website{% endblock %}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;link&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;rel&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;stylesheet&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;href&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;{{ url_for(&#39;static&#39;, filename=&#39;style.css&#39;) }}&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;header&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;My Website&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;header&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;main&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% block content %}{% endblock %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;main&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;footer&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;© 2024 My Website&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;footer&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;templates-index-html&#34;&gt;&lt;a href=&#34;#templates-index-html&#34; class=&#34;headerlink&#34; title=&#34;templates/index.html&#34;&gt;&lt;/a&gt;&lt;code&gt;templates/index.html&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;{% extends &#34;base.html&#34; %}

{% block title %}Home Page{% endblock %}

{% block content %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Welcome to the Home Page&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    {% if user_is_logged_in %}
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Welcome back, {{ username }}!&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    {% else %}
        &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Please log in to access your account.&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;p&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    {% endif %}

    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;ul&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% for item in items %}
            &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;li&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;{{ item }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;li&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% endfor %}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;ul&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
{% endblock %}&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;static-style-css&#34;&gt;&lt;a href=&#34;#static-style-css&#34; class=&#34;headerlink&#34; title=&#34;static/style.css&#34;&gt;&lt;/a&gt;&lt;code&gt;static/style.css&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-css&#34; data-language=&#34;css&#34;&gt;&lt;code class=&#34;language-css&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;/* 示例样式 */&lt;/span&gt;
&lt;span class=&#34;token selector&#34;&gt;body&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;font-family&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; Arial&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sans-serif&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

&lt;span class=&#34;token selector&#34;&gt;header&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;background-color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; #333&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; #fff&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;padding&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; 1em&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;text-align&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; center&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;

&lt;span class=&#34;token selector&#34;&gt;footer&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;background-color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; #333&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; #fff&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;padding&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; 0.5em&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
    &lt;span class=&#34;token property&#34;&gt;text-align&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; center&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h2 id=&#34;Flask-表单处理&#34;&gt;&lt;a href=&#34;#Flask-表单处理&#34; class=&#34;headerlink&#34; title=&#34;Flask 表单处理&#34;&gt;&lt;/a&gt;Flask 表单处理&lt;/h2&gt;&lt;p&gt;在 Flask 中，表单处理是一个常见的功能，它涉及接收用户输入、验证数据以及相应地进行处理。Flask 提供了 &lt;code&gt;Flask-WTF&lt;/code&gt; 扩展，使得表单的创建、验证和处理变得更加简单和强大。下面将详细介绍如何在 Flask 中处理表单，包括安装 Flask-WTF、创建表单、验证表单、显示表单错误和处理表单数据。&lt;/p&gt;
&lt;h3 id=&#34;1-安装-Flask-WTF&#34;&gt;&lt;a href=&#34;#1-安装-Flask-WTF&#34; class=&#34;headerlink&#34; title=&#34;1. 安装 Flask-WTF&#34;&gt;&lt;/a&gt;1. 安装 Flask-WTF&lt;/h3&gt;&lt;p&gt;在开始之前，你需要确保安装了 &lt;code&gt;Flask-WTF&lt;/code&gt;。可以通过 &lt;code&gt;pip&lt;/code&gt; 进行安装：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; Flask-WTF&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;2-创建-Flask-应用&#34;&gt;&lt;a href=&#34;#2-创建-Flask-应用&#34; class=&#34;headerlink&#34; title=&#34;2. 创建 Flask 应用&#34;&gt;&lt;/a&gt;2. 创建 Flask 应用&lt;/h3&gt;&lt;p&gt;创建一个简单的 Flask 应用并设置基本配置。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; render_template
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask_wtf &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; FlaskForm
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; wtforms &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; StringField&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; SubmitField
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; wtforms&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;validators &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; DataRequired

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;config&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;SECRET_KEY&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;your_secret_key&#39;&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 设置安全密钥&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;3-创建表单类&#34;&gt;&lt;a href=&#34;#3-创建表单类&#34; class=&#34;headerlink&#34; title=&#34;3. 创建表单类&#34;&gt;&lt;/a&gt;3. 创建表单类&lt;/h3&gt;&lt;p&gt;使用 &lt;code&gt;Flask-WTF&lt;/code&gt; 创建表单类，定义所需的字段和验证规则。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;MyForm&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;FlaskForm&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    username &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; StringField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Username&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; validators&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;DataRequired&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    submit &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; SubmitField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Submit&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;StringField&lt;/code&gt;：表示一个文本输入字段。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;DataRequired()&lt;/code&gt;：确保字段不为空。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;4-渲染表单&#34;&gt;&lt;a href=&#34;#4-渲染表单&#34; class=&#34;headerlink&#34; title=&#34;4. 渲染表单&#34;&gt;&lt;/a&gt;4. 渲染表单&lt;/h3&gt;&lt;p&gt;在视图函数中实例化表单并传递给模板。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; methods&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;GET&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    form &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; MyForm&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; form&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;validate_on_submit&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 验证表单数据&lt;/span&gt;
        username &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; form&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;data  &lt;span class=&#34;token comment&#34;&gt;# 获取输入的用户名&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#39;Hello, &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;!&#39;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;index.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; form&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;form&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;validate_on_submit()&lt;/code&gt;：检查请求方法是否为 POST 并验证表单数据。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;form.username.data&lt;/code&gt;：访问用户输入的值。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;5-创建模板&#34;&gt;&lt;a href=&#34;#5-创建模板&#34; class=&#34;headerlink&#34; title=&#34;5. 创建模板&#34;&gt;&lt;/a&gt;5. 创建模板&lt;/h3&gt;&lt;p&gt;在 &lt;code&gt;templates&lt;/code&gt; 文件夹中创建一个模板 &lt;code&gt;index.html&lt;/code&gt;，用于显示表单。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;&amp;lt;!-- templates/index.html --&amp;gt;&lt;/span&gt;
&lt;span class=&#34;token doctype&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;!&lt;/span&gt;&lt;span class=&#34;token doctype-tag&#34;&gt;DOCTYPE&lt;/span&gt; &lt;span class=&#34;token name&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;html&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;lang&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;en&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;meta&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;charset&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;UTF-8&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Flask Form Example&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Enter your username&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;form&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;method&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;POST&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {{ form.hidden_tag() }}  &lt;span class=&#34;token comment&#34;&gt;&amp;lt;!-- 防止 CSRF 攻击 --&amp;gt;&lt;/span&gt;
        {{ form.username.label }} {{ form.username(size=20) }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;br&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% for error in form.username.errors %}
            &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;span&lt;/span&gt; &lt;span class=&#34;token special-attr&#34;&gt;&lt;span class=&#34;token attr-name&#34;&gt;style&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;span class=&#34;token value css language-css&#34;&gt;&lt;span class=&#34;token property&#34;&gt;color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; red&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;[{{ error }}]&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;span&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;br&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% endfor %}
        {{ form.submit() }}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;form&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;ul&gt;
&lt;li&gt;&lt;code&gt;{{ form.hidden_tag() }}&lt;/code&gt;：生成隐藏的 CSRF 令牌，增强安全性。&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;{% for error in form.username.errors %}&lt;/code&gt; 循环显示字段的验证错误。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;6-处理表单错误&#34;&gt;&lt;a href=&#34;#6-处理表单错误&#34; class=&#34;headerlink&#34; title=&#34;6. 处理表单错误&#34;&gt;&lt;/a&gt;6. 处理表单错误&lt;/h3&gt;&lt;p&gt;如果表单验证失败，Flask-WTF 会自动将错误信息存储在字段的 &lt;code&gt;errors&lt;/code&gt; 属性中。在模板中，可以通过条件判断显示相应的错误消息。&lt;/p&gt;
&lt;h3 id=&#34;7-完整示例-1&#34;&gt;&lt;a href=&#34;#7-完整示例-1&#34; class=&#34;headerlink&#34; title=&#34;7. 完整示例&#34;&gt;&lt;/a&gt;7. 完整示例&lt;/h3&gt;&lt;p&gt;以下是一个完整的 Flask 应用示例，展示了如何使用 Flask-WTF 处理表单。&lt;/p&gt;
&lt;h4 id=&#34;项目结构-2&#34;&gt;&lt;a href=&#34;#项目结构-2&#34; class=&#34;headerlink&#34; title=&#34;项目结构&#34;&gt;&lt;/a&gt;项目结构&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;my_flask_app/
├── app.py                   &lt;span class=&#34;token comment&#34;&gt;# Flask 应用主文件&lt;/span&gt;
└── templates/
    └── index.html          &lt;span class=&#34;token comment&#34;&gt;# 表单模板&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;app-py-1&#34;&gt;&lt;a href=&#34;#app-py-1&#34; class=&#34;headerlink&#34; title=&#34;app.py&#34;&gt;&lt;/a&gt;&lt;code&gt;app.py&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;码&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; render_template
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; flask_wtf &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; FlaskForm
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; wtforms &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; StringField&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; SubmitField
&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; wtforms&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;validators &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; DataRequired

app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;config&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;SECRET_KEY&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;your_secret_key&#39;&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 设置安全密钥&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;MyForm&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;FlaskForm&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    username &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; StringField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Username&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; validators&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;DataRequired&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    submit &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; SubmitField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Submit&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; methods&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;GET&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    form &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; MyForm&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; form&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;validate_on_submit&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 验证表单数据&lt;/span&gt;
        username &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; form&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;data  &lt;span class=&#34;token comment&#34;&gt;# 获取输入的用户名&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#39;Hello, &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;username&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;!&#39;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;index.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; form&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;form&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; __name__ &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;__main__&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;run&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;debug&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;True&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;templates-index-html-1&#34;&gt;&lt;a href=&#34;#templates-index-html-1&#34; class=&#34;headerlink&#34; title=&#34;templates/index.html&#34;&gt;&lt;/a&gt;&lt;code&gt;templates/index.html&lt;/code&gt;&lt;/h4&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&lt;span class=&#34;token doctype&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;!&lt;/span&gt;&lt;span class=&#34;token doctype-tag&#34;&gt;DOCTYPE&lt;/span&gt; &lt;span class=&#34;token name&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;html&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;lang&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;en&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;meta&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;charset&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;UTF-8&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Flask Form Example&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;title&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;head&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;Enter your username&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;h1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;form&lt;/span&gt; &lt;span class=&#34;token attr-name&#34;&gt;method&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;POST&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {{ form.hidden_tag() }}  &lt;span class=&#34;token comment&#34;&gt;&amp;lt;!-- 防止 CSRF 攻击 --&amp;gt;&lt;/span&gt;
        {{ form.username.label }} {{ form.username(size=20) }}&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;br&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% for error in form.username.errors %}
            &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;span&lt;/span&gt; &lt;span class=&#34;token special-attr&#34;&gt;&lt;span class=&#34;token attr-name&#34;&gt;style&lt;/span&gt;&lt;span class=&#34;token attr-value&#34;&gt;&lt;span class=&#34;token punctuation attr-equals&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;span class=&#34;token value css language-css&#34;&gt;&lt;span class=&#34;token property&#34;&gt;color&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt; red&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;[{{ error }}]&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;span&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;br&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
        {% endfor %}
        {{ form.submit() }}
    &lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;form&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;body&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token tag&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;/&lt;/span&gt;html&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;8-添加更多字段和验证器&#34;&gt;&lt;a href=&#34;#8-添加更多字段和验证器&#34; class=&#34;headerlink&#34; title=&#34;8. 添加更多字段和验证器&#34;&gt;&lt;/a&gt;8. 添加更多字段和验证器&lt;/h3&gt;&lt;p&gt;可以使用 &lt;code&gt;WTForms&lt;/code&gt; 提供的多种字段类型和验证器来扩展表单功能。例如，可以添加 &lt;code&gt;EmailField&lt;/code&gt;、&lt;code&gt;PasswordField&lt;/code&gt;、&lt;code&gt;SelectField&lt;/code&gt; 等。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; wtforms &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; EmailField&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; PasswordField&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; SelectField

&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;ExtendedForm&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;FlaskForm&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    username &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; StringField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Username&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; validators&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;DataRequired&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    email &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; EmailField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Email&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; validators&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;DataRequired&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    password &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; PasswordField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Password&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; validators&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;DataRequired&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    options &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; SelectField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Options&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; choices&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;opt1&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;Option 1&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;opt2&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;Option 2&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    submit &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; SubmitField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Submit&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;9-处理文件上传&#34;&gt;&lt;a href=&#34;#9-处理文件上传&#34; class=&#34;headerlink&#34; title=&#34;9. 处理文件上传&#34;&gt;&lt;/a&gt;9. 处理文件上传&lt;/h3&gt;&lt;p&gt;Flask-WTF 也支持文件上传，可以使用 &lt;code&gt;FileField&lt;/code&gt;。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; wtforms &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; FileField

&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;UploadForm&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;FlaskForm&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token builtin&#34;&gt;file&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; FileField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;File&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    submit &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; SubmitField&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Upload&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/upload&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; methods&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;GET&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;POST&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;upload_file&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    form &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; UploadForm&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; form&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;validate_on_submit&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token builtin&#34;&gt;file&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; form&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token builtin&#34;&gt;file&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;data
        &lt;span class=&#34;token comment&#34;&gt;# 处理文件上传&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#39;File &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;token builtin&#34;&gt;file&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;filename&lt;span class=&#34;token punctuation&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt; uploaded successfully!&#39;&lt;/span&gt;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;upload.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; form&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;form&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;10-保护表单安全&#34;&gt;&lt;a href=&#34;#10-保护表单安全&#34; class=&#34;headerlink&#34; title=&#34;10. 保护表单安全&#34;&gt;&lt;/a&gt;10. 保护表单安全&lt;/h3&gt;&lt;p&gt;使用 &lt;code&gt;SECRET_KEY&lt;/code&gt; 保护表单，防止 CSRF 攻击，确保所有表单都使用 &lt;code&gt;form.hidden_tag()&lt;/code&gt; 生成 CSRF 令牌。&lt;/p&gt;
&lt;h2 id=&#34;出现找不到渲染文件index-html&#34;&gt;&lt;a href=&#34;#出现找不到渲染文件index-html&#34; class=&#34;headerlink&#34; title=&#34;出现找不到渲染文件index.html&#34;&gt;&lt;/a&gt;出现找不到渲染文件index.html&lt;/h2&gt;&lt;p&gt;检查目录结构，添加这个template_folder=’app/templates’创建框架&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;app &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Flask&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;__name__&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; template_folder&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;app/templates&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token decorator annotation punctuation&#34;&gt;@app&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;route&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;/&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;home&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; render_template&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;index.html&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;直接点说python需要从你的路由所在路径找起， template_folder就是指定路径，加入你的路由在app文件夹下，不用指定路径就能直接找到，在外面，例如和app同级，就可以写路径为&lt;code&gt;.app/templates&lt;/code&gt;，记住最重要的是你的路由所在位置算起。&lt;/p&gt;

 &lt;h2 id=&#34;pip安装&#34;&gt;&lt;a href=&#34;#pip安装&#34; class=&#34;headerlink&#34; title=&#34;pip安装&#34;&gt;&lt;/a&gt;pip安装&lt;/h2&gt;&lt;h3 id=&#34;windows&#34;&gt;&lt;a href=&#34;#windows&#34; class=&#34;headerlink&#34; title=&#34;windows&#34;&gt;&lt;/a&gt;windows&lt;/h3&gt;&lt;p&gt;不写了&lt;/p&gt;
&lt;h3 id=&#34;linux（ubuntu）&#34;&gt;&lt;a href=&#34;#linux（ubuntu）&#34; class=&#34;headerlink&#34; title=&#34;linux（ubuntu）&#34;&gt;&lt;/a&gt;linux（ubuntu）&lt;/h3&gt;&lt;h2 id=&#34;pip的使用&#34;&gt;&lt;a href=&#34;#pip的使用&#34; class=&#34;headerlink&#34; title=&#34;pip的使用&#34;&gt;&lt;/a&gt;pip的使用&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token parameter variable&#34;&gt;--version&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;#显示版本和路径&lt;/span&gt;

pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-U&lt;/span&gt; pip &lt;span class=&#34;token comment&#34;&gt;#升级pip&lt;/span&gt;

pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; SomePackage              &lt;span class=&#34;token comment&#34;&gt;# 最新版本&lt;/span&gt;
pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token assign-left variable&#34;&gt;SomePackage&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1.0&lt;/span&gt;.4       &lt;span class=&#34;token comment&#34;&gt;# 指定版本&lt;/span&gt;
pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;SomePackage&amp;gt;=1.0.4&#39;&lt;/span&gt;     &lt;span class=&#34;token comment&#34;&gt;# 最小版本&lt;/span&gt;

pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;--upgrade&lt;/span&gt; SomePackage   &lt;span class=&#34;token comment&#34;&gt;#升级包&lt;/span&gt;

pip uninstall SomePackage  &lt;span class=&#34;token comment&#34;&gt;#卸载包&lt;/span&gt;

pip search SomePackage  &lt;span class=&#34;token comment&#34;&gt;#搜索包&lt;/span&gt;

pip show   &lt;span class=&#34;token comment&#34;&gt;#显示安装包信息 &lt;/span&gt;

pip show &lt;span class=&#34;token parameter variable&#34;&gt;-f&lt;/span&gt; SomePackage  &lt;span class=&#34;token comment&#34;&gt;#查看指定包的详细信息&lt;/span&gt;

pip list  &lt;span class=&#34;token comment&#34;&gt;#列出已安装的包&lt;/span&gt;

pip list &lt;span class=&#34;token parameter variable&#34;&gt;-o&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;#查看可升级的包&lt;/span&gt;

pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; https://pypi.tuna.tsinghua.edu.cn/simple some-package  &lt;span class=&#34;token comment&#34;&gt;#指定源安装&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;python &lt;span class=&#34;token parameter variable&#34;&gt;-m&lt;/span&gt; site &lt;span class=&#34;token comment&#34;&gt;# 列出所有库的解释路径&lt;/span&gt;
or
&lt;span class=&#34;token function&#34;&gt;import&lt;/span&gt; sys
print&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys.path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

 &lt;h1 id=&#34;Windows下安装python&#34;&gt;&lt;a href=&#34;#Windows下安装python&#34; class=&#34;headerlink&#34; title=&#34;Windows下安装python&#34;&gt;&lt;/a&gt;Windows下安装python&lt;/h1&gt;&lt;h2 id=&#34;安装&#34;&gt;&lt;a href=&#34;#安装&#34; class=&#34;headerlink&#34; title=&#34;安装&#34;&gt;&lt;/a&gt;安装&lt;/h2&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;安装包下载，&lt;a href=&#34;https://www.python.org/downloads/windows/&#34;&gt;Python Releases for Windows | Python.org&lt;/a&gt;，根据自己计算机的配置选择合适版本安装，我选择了一个3.8.8的版本测试&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;双击开始安装&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.dadream.eu.org/images/2024/07/db93018a35a4cbb5f0d721d791cde78d.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;可以直接选择Install Now，建议选择下面自定义路径方便管理，勾选Add Path，Next，Next&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.dadream.eu.org/images/2024/07/294ff70828ba5b135919baa57679348f.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;勾选如图选项，路径自选，Install（除默认的也可以不选）&lt;/p&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;&lt;p&gt;安装成功后，win+R ，输入cmd运行命令行，运行命令&lt;code&gt;python -V&lt;/code&gt;，&lt;code&gt;pip -V&lt;/code&gt;，显示版本则安装成功&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;若没点Add Path 可以重新装，点击安装包，或者自行添加&lt;/p&gt;
&lt;p&gt;win+R ，输入contro打开控制面板，系统和安全-&amp;gt;系统-&amp;gt;高级系统设置-&amp;gt;环境变量&lt;/p&gt;
&lt;p&gt;添加如下&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.dadream.eu.org/images/2024/07/01a0f7aae246452754a2d3c6e3d20dd5.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h2 id=&#34;安装多个不同版本&#34;&gt;&lt;a href=&#34;#安装多个不同版本&#34; class=&#34;headerlink&#34; title=&#34;安装多个不同版本&#34;&gt;&lt;/a&gt;安装多个不同版本&lt;/h2&gt;&lt;p&gt;按照上述安装步骤选择几个不同版本的安装&lt;/p&gt;
&lt;p&gt;已安装两个为例，我安装了一个2.x和3.x版本的&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.dadream.eu.org/images/2024/07/152407932b02733a7a503903a7e297d6.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;进入一个目录，复制&lt;code&gt;python.exe&lt;/code&gt;，&lt;code&gt;pythonw.exe&lt;/code&gt;两个文件，并且重命名，调用时就是用你重命的名，可以随时改，下图为结果&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.dadream.eu.org/images/2024/07/6ff4d0fb58245efa994e4206e916d191.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;进入Scripts&lt;/p&gt;
&lt;p&gt;正常应该是存在两个文件（&lt;code&gt;pip.exe&lt;/code&gt;、&lt;code&gt;pipx.exe&lt;/code&gt;），如没有后者，自己复制改一个，用上述命令测试时候成功&lt;/p&gt;
&lt;p&gt;其他的版本一个意思，我一般会留一个不改，直接用&lt;code&gt;python&lt;/code&gt;调用当做主用版本，毕竟少打一个字母……&lt;/p&gt;

 &lt;h1 id=&#34;python学习&#34;&gt;&lt;a href=&#34;#python学习&#34; class=&#34;headerlink&#34; title=&#34;python学习&#34;&gt;&lt;/a&gt;python学习&lt;/h1&gt;&lt;h2 id=&#34;基础语法&#34;&gt;&lt;a href=&#34;#基础语法&#34; class=&#34;headerlink&#34; title=&#34;基础语法&#34;&gt;&lt;/a&gt;基础语法&lt;/h2&gt;&lt;h3 id=&#34;标识符&#34;&gt;&lt;a href=&#34;#标识符&#34; class=&#34;headerlink&#34; title=&#34;标识符&#34;&gt;&lt;/a&gt;标识符&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;首字母必须是字母或者下划线&lt;code&gt;_&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;其他部分由字母、数字、下划线组成&lt;/li&gt;
&lt;li&gt;大小写敏感&lt;/li&gt;
&lt;li&gt;python3 可中文也可非ASCII标识符&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;python保留字&#34;&gt;&lt;a href=&#34;#python保留字&#34; class=&#34;headerlink&#34; title=&#34;python保留字&#34;&gt;&lt;/a&gt;python保留字&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; keyword
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;keyword&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;kwlist&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;False&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;None&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;True&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;and&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;as&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;assert&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;async&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;await&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;break&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;class&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;continue&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;def&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;del&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;elif&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;else&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;except&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;finally&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;for&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;from&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;global&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;if&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;import&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;in&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;is&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;lambda&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;nonlocal&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;not&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;or&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;pass&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;raise&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;return&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;try&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;while&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;with&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;yield&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;注释&#34;&gt;&lt;a href=&#34;#注释&#34; class=&#34;headerlink&#34; title=&#34;注释&#34;&gt;&lt;/a&gt;注释&lt;/h3&gt;&lt;p&gt;python中&lt;code&gt;&#39;&lt;/code&gt;和&lt;code&gt;&#34;&lt;/code&gt;一样&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;#单行注释

&#39;&#39;&#39;
多行注释
&#39;&#39;&#39;

&#34;&#34;&#34;
多行注释
&#34;&#34;&#34;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;缩进&#34;&gt;&lt;a href=&#34;#缩进&#34; class=&#34;headerlink&#34; title=&#34;缩进&#34;&gt;&lt;/a&gt;缩进&lt;/h3&gt;&lt;p&gt;python不使用大括号，使用缩进对齐&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; expression &lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    XXX
&lt;span class=&#34;token keyword&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    XXX&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;多行连接&#34;&gt;&lt;a href=&#34;#多行连接&#34; class=&#34;headerlink&#34; title=&#34;多行连接&#34;&gt;&lt;/a&gt;多行连接&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;var &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; \
	 &lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; \
    &lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;var&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;#6&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;数字类型&#34;&gt;&lt;a href=&#34;#数字类型&#34; class=&#34;headerlink&#34; title=&#34;数字类型&#34;&gt;&lt;/a&gt;数字类型&lt;/h3&gt;&lt;p&gt;python中数字有四种类型：整数、布尔型、浮点数和复数&lt;/p&gt;
&lt;h3 id=&#34;字符串&#34;&gt;&lt;a href=&#34;#字符串&#34; class=&#34;headerlink&#34; title=&#34;字符串&#34;&gt;&lt;/a&gt;字符串&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;python中单引号、双引号使用完全相同&lt;/li&gt;
&lt;li&gt;转义字符&lt;code&gt;\&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;r&#39;test\ntest&#39;&lt;/code&gt;，&lt;code&gt;r&lt;/code&gt;可以使&lt;code&gt;\n&lt;/code&gt;不转义&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&#34;this &#34; &#34;is &#34; &#34;string&#34;&lt;/code&gt;输出&lt;code&gt;this is string&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;+&lt;/code&gt;运算符连接字符，&lt;code&gt;*&lt;/code&gt;运算符重复字符&lt;/li&gt;
&lt;li&gt;检索从左到右从0开始，从右到左从-1开始&lt;/li&gt;
&lt;li&gt;一个字符就是一个长度为1的字符串&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;var &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;this &#34;&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;is &#34;&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;string&#34;&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;var&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
