&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;pop_obj&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
